extern char **environ;

/* Fibers hand-switch the C stack via swapcontext (see DIAMOND_FIBER_STACK_SIZE
 * and friends below), which ASan's stack-use-after-return instrumentation
 * doesn't know about on its own -- it associates each real stack address
 * range with at most one live "fake stack" region, and a manual switch to a
 * different memory region (a fiber's own mmapped stack) without telling it
 * looks the same as the previous occupant having returned. The official
 * fix is these paired annotation calls around every swapcontext, which are
 * a no-op unless built with ASan. See docs/threads.md. */
#if defined(__SANITIZE_ADDRESS__) || \
    (defined(__has_feature) && __has_feature(address_sanitizer))
#define DIAMOND_ASAN_FIBERS 1
#include <sanitizer/common_interface_defs.h>

/* A switch back out of a fiber (yield, or the final completing swap) needs
 * real bounds for whatever it's switching *to*, same as switching into a
 * fiber does -- an unknown/null destination isn't the harmless "just skip
 * detection there" the API docs suggest: real testing here (a deeply
 * recursive fiber resumed a second time, allocating under GC stress) showed
 * it still misattributes the *resuming* fiber's own still-live ancestor
 * frames as returned. Each OS thread's own native stack bounds are queried
 * once, lazily, and cached; a resume_target that belongs to another fiber
 * (nested Fiber.resume from within a fiber) instead uses that fiber's own
 * known mmap region. */
static thread_local void *diamond_native_stack_bottom;
static thread_local size_t diamond_native_stack_size;
static thread_local bool diamond_native_stack_known;

static void diamond_ensure_native_stack_bounds(void) {
    if (diamond_native_stack_known) return;
    diamond_native_stack_known = true;
    pthread_attr_t attr;
    if (pthread_getattr_np(pthread_self(), &attr) != 0) return;
    void *addr = nullptr; size_t size = 0;
    if (pthread_attr_getstack(&attr, &addr, &size) == 0) {
        diamond_native_stack_bottom = addr;
        diamond_native_stack_size = size;
    }
    pthread_attr_destroy(&attr);
}

/* Bounds of whatever fiber->resumer_fiber (if any) is resuming into, for
 * the "switching back out" annotation calls: another fiber's own known
 * mmap region when nested, otherwise this thread's own native stack. */
static void diamond_resume_target_bounds(const DiamondFiber *fiber,
        const void **bottom, size_t *size) {
    if (fiber->resumer_fiber != nullptr) {
        *bottom = fiber->resumer_fiber->context.uc_stack.ss_sp;
        *size = fiber->resumer_fiber->context.uc_stack.ss_size;
        return;
    }
    diamond_ensure_native_stack_bounds();
    *bottom = diamond_native_stack_bottom;
    *size = diamond_native_stack_size;
}
#endif

enum { DIAMOND_INLINE_REGISTER_COUNT = 256 };

/* How often run_chunk's own dispatch loop actually calls clock_gettime to
 * check a configured DIAMOND_MAX_WALL_MILLISECONDS budget (docs/sandbox.md's
 * own "Resource limits" section) -- masked against vm->instructions_executed
 * rather than checked every dispatch, since the clock read itself (unlike
 * the instruction-count comparison right next to it) is real, non-trivial
 * cost. Bounds the worst-case overshoot past the configured budget to
 * "however long this many opcodes take," negligible next to any
 * millisecond-scale budget someone would actually configure. Must be a
 * power of two minus one for the `&` mask below to work. */
enum { DIAMOND_RESOURCE_LIMIT_CLOCK_CHECK_MASK = 4095 };

/* Card size for the generational GC's Array/Hash write barrier -- see
 * mark_card_dirty's own comment (below, near gc_write_barrier) for why
 * only these two kinds need index-granularity remembering. Declared
 * this early because mark_remembered_set (just below) already needs it
 * to size its own card-index arithmetic. */
enum { DIAMOND_GC_CARD_SIZE = 64 };

typedef enum PendingKind : uint8_t {
    PENDING_NONE,
    PENDING_NORMAL,
    PENDING_RETURN,
    PENDING_EXCEPTION,
    /* An ensure block run while a block's non-local return/break unwinds
     * through this frame; END_ENSURE resumes the unwinding. */
    PENDING_NONLOCAL,
} PendingKind;

typedef struct PendingUnwind {
    PendingKind kind;
    DiamondValue value;
    size_t continuation;
    uint64_t nonlocal_target;
    bool nonlocal_is_break;
} PendingUnwind;

typedef enum HandlerKind : uint8_t { HANDLER_RESCUE, HANDLER_ENSURE, HANDLER_ACTIVE_ENSURE } HandlerKind;

typedef struct UnwindHandler {
    HandlerKind kind;
    size_t target;
    uint16_t destination;
    uint8_t type_count;
    uint8_t types[8];
    bool enabled;
    PendingUnwind saved_pending;
} UnwindHandler;

/* An active ensure remains on the handler stack as an unwind boundary.
 * Its saved continuation survives nested cleanup, but is discarded when a
 * new exception or return escapes that cleanup. */
static UnwindHandler pop_unwind_handler(UnwindHandler *handlers,
        size_t *count,PendingUnwind *pending) {
    const UnwindHandler handler=handlers[--*count];
    if(handler.kind==HANDLER_ACTIVE_ENSURE)*pending=handler.saved_pending;
    return handler;
}

static size_t enter_ensure(UnwindHandler *handler,PendingUnwind *pending,
        PendingUnwind next) {
    handler->kind=HANDLER_ACTIVE_ENSURE;
    handler->saved_pending=*pending;
    *pending=next;
    return handler->target;
}

typedef struct DiamondFrame {
    struct DiamondFrame *previous;
    DiamondValue *registers;
    PendingUnwind *pending;
    UnwindHandler *handlers;
    size_t *handler_count;
    size_t register_count;
    /* Backtrace support (Exception#backtrace): the owning chunk plus a
     * pointer to run_chunk's own `instruction_offset` local, not a copied
     * value -- a suspended ancestor frame is a real, live C stack frame
     * blocked inside a nested call, so reading through the pointer always
     * reflects its current instruction (the call site) with no need to
     * sync a copy on every dispatch iteration. Valid for exactly the
     * frame's own lifetime, same as the frame struct itself. */
    const DiamondChunk *chunk;
    const size_t *instruction_offset;
    /* This activation's serial, and its method's (its own, unless it's a
     * do-block, whose method is the one its closure was created in). */
    uint64_t serial;
    uint64_t home;
} DiamondFrame;

/* JIT trampolines for Phase 2c (docs/internal/jit-design.md) -- DiamondFrame
 * is private to this file, so jit.c can never construct or link one
 * directly; it only ever reserves opaque bytes on its own native stack and
 * calls these to manage them, the same "risky logic stays in real C, not
 * hand-rolled machine code" pattern already used for SET_IVAR/INDEX_GET/
 * CHECK_TYPE. diamond_jit_frame_size is called once per *compile* (not per
 * generated call) so jit.c learns the exact byte count to reserve without
 * a hardcoded constant that could silently drift out of sync with this
 * struct's own layout -- unlike DIAMOND_JIT_MAX_REGISTERS (a bare enum,
 * nothing to query), sizeof() on a real struct is exactly this available
 * here. The extra trailing size_t past the frame itself is instruction_
 * offset's own backing storage: that field is a *pointer* to a live value
 * for the frame's whole lifetime (see its own struct comment above), not
 * a copy, and a JIT'd function has no `ip`-like local of its own to point
 * at -- this reserves one, initialized to 0 (a synthetic placeholder;
 * this JIT compiles no begin/rescue and nothing it calls through these
 * trampolines can itself raise, so no code path today ever reads it back
 * for a real backtrace, but a future one might). */
size_t diamond_jit_frame_size(void) {
    return sizeof(DiamondFrame) + sizeof(size_t);
}

void diamond_jit_frame_push(void *frame_storage, DiamondVm *vm,
        DiamondValue *registers, size_t register_count, const DiamondChunk *chunk) {
    DiamondFrame *frame = (DiamondFrame *)frame_storage;
    size_t *offset_storage = (size_t *)(frame + 1);
    *offset_storage = 0;
    *frame = (DiamondFrame){
        .previous = vm->frames,
        .registers = registers,
        .pending = nullptr,
        .register_count = register_count,
        .chunk = chunk,
        .instruction_offset = offset_storage,
    };
    vm->frames = frame;
}

void diamond_jit_frame_pop(DiamondVm *vm) {
    DiamondFrame *frame = (DiamondFrame *)vm->frames;
    vm->frames = frame->previous;
}

/* Native backing struct for DiamondThreadHandle (object.h) -- see
 * docs/threads.md. `child_vm`/`child_program` are this thread's own,
 * fully independent heap/GC and a byte-for-byte memcpy clone of whatever
 * DiamondProgram was ambient at Thread.new time (see thread_new_helper),
 * never shared with the spawning thread's own program or any other
 * thread's clone. `function_index`/`args`/`arg_count` are captured at
 * spawn time so the OS-thread entry point (thread_entry_trampoline) has
 * everything it needs with no further reference back into the spawning
 * VM's own state. `result`/`raised` are only meaningful once `finished`
 * is true; `finished` is the only field the spawning thread may read
 * without holding `join_lock` (a plain atomic flag, set exactly once,
 * read-only afterward -- .alive?() polls it without blocking).
 * `join_lock` guards the joined/not-yet-joined transition so .join() is
 * safely callable more than once (pthread_join itself is not). */
typedef struct DiamondThread {
    pthread_t handle;
    /* True only once pthread_create actually succeeded for `handle` --
     * distinguishes "there's a real OS thread that must be pthread_join'd"
     * from the synchronous-stub path (Thread.new runs the callable inline,
     * no OS thread ever created) and from a failed pthread_create (also no
     * real thread to join). free_thread only calls pthread_join when this
     * is true. */
    bool spawned;
    DiamondVm *child_vm;
    DiamondProgram *child_program;
    uint16_t function_index;
    DiamondValue args[DIAMOND_MAX_ARGUMENTS];
    uint8_t arg_count;
    /* Three, mutually exclusive outcomes once `finished` is true:
     * (1) plain return -- `raised`/`internal_failure` both false, `result`
     *     is the returned value; (2) the target raised, uncaught -- only
     *     `raised` true, `result` is the actual Diamond exception instance
     *     to re-raise (still living in child_vm's own heap; .join() deep-
     *     copies it back, same as an ordinary return value); (3) the
     *     child hit an internal VM failure that was never a clean Diamond-
     *     level raise (stack overflow, invalid bytecode, ...) -- only
     *     `internal_failure` true, `result` unused, .join() reads
     *     child_vm->error directly (still alive at that point) to build a
     *     fresh ThreadError. */
    DiamondValue result;
    bool raised;
    bool internal_failure;
    atomic_bool finished;
    bool joined;
    pthread_mutex_t join_lock;
} DiamondThread;

/* Called with channel->lock held. Writes never block; a full pipe already
 * contains a wakeup. Waiters unlink under this same lock before closing their
 * descriptors, so no writer can retain a stale pointer or write to a closed
 * reader. No user code, allocation, or second channel lock is involved. */
static void notify_channel_waiters(DiamondChannel *channel) {
    for(ChannelWaitLink *waiter=channel->waiters;waiter!=nullptr;waiter=waiter->next) {
        const char byte=1;
        ssize_t written;
        do {written=write(waiter->write_fd,&byte,1);} while(written<0&&errno==EINTR);
    }
}

typedef struct ChannelWaitRegistration {
    DiamondChannel *channel;
    ChannelWaitLink link;
} ChannelWaitRegistration;

/* A readiness wait does not consume data or reserve capacity. The caller
 * retries its operation after waking. Registration and readiness checks share
 * each channel's lock: a transition either precedes the check or writes to
 * the already-registered pipe. This closes the check/sleep lost-wakeup gap.
 * Receiver/argument registers keep all handles alive for this entire call.
 * fds has room for one extra descriptor after fd_count. target is NULL for
 * IO.poll, which waits on its supplied fds plus cancellation channels.
 * select_drained is non-NULL only for Channel.select: the Array's channels
 * are then candidates rather than cancellation sources, ready when they hold
 * a value or close, except entries the caller already saw closed and drained
 * (select_drained[i]) -- those can never become ready again and would
 * otherwise spin the wait. */
DiamondVmStatus cancellable_wait_helper(DiamondVm *vm,DiamondChannel *target,
        bool writable,DiamondValue cancellations,DiamondValue deadline_value,
        struct pollfd *fds,nfds_t fd_count,const bool *select_drained) {
    if(cancellations.kind!=DIAMOND_VALUE_OBJECT ||
       cancellations.as.object->kind!=DIAMOND_OBJECT_ARRAY) {
        snprintf(vm->error,sizeof vm->error,"channel wait cancellations must be an Array of Channels");
        return DIAMOND_VM_TYPE_ERROR;
    }
    const DiamondArray *array=(const DiamondArray *)cancellations.as.object;
    for(size_t i=0;i<array->count;i++) {
        if(array->values[i].kind!=DIAMOND_VALUE_OBJECT ||
           array->values[i].as.object->kind!=DIAMOND_OBJECT_CHANNEL) {
            snprintf(vm->error,sizeof vm->error,"channel wait cancellations must be an Array of Channels");
            return DIAMOND_VM_TYPE_ERROR;
        }
    }
    const bool timed=deadline_value.kind!=DIAMOND_VALUE_NIL;
    double deadline=0;
    if(timed) {
        if(deadline_value.kind!=DIAMOND_VALUE_FLOAT || !isfinite(deadline_value.as.real)) {
            snprintf(vm->error,sizeof vm->error,"channel wait deadline must be a finite monotonic Float or nil");
            return DIAMOND_VM_TYPE_ERROR;
        }
        deadline=deadline_value.as.real;
    }
    if(array->count>=SIZE_MAX/sizeof(ChannelWaitRegistration)-1)
        return DIAMOND_VM_OUT_OF_MEMORY;
    const size_t target_count=target==nullptr?0:1;
    const size_t count=array->count+target_count;
    ChannelWaitRegistration *registrations=calloc(count==0?1:count,sizeof *registrations);
    if(registrations==nullptr)return DIAMOND_VM_OUT_OF_MEMORY;
    int descriptors[2];
    if(pipe(descriptors)!=0) {
        free(registrations);
        snprintf(vm->error,sizeof vm->error,"channel wait pipe: %s",strerror(errno));
        return DIAMOND_VM_IO_ERROR;
    }
    for(size_t i=0;i<2;i++) {
        if(fcntl(descriptors[i],F_SETFD,FD_CLOEXEC)<0 ||
           fcntl(descriptors[i],F_SETFL,O_NONBLOCK)<0) {
            const int error=errno;
            close(descriptors[0]);close(descriptors[1]);free(registrations);
            snprintf(vm->error,sizeof vm->error,"channel wait pipe flags: %s",strerror(error));
            return DIAMOND_VM_IO_ERROR;
        }
    }
    fds[fd_count]=(struct pollfd){.fd=descriptors[0],.events=POLLIN};
    bool ready=false;
    for(size_t i=0;i<count;i++) {
        DiamondChannel *channel=i<target_count?target:
            ((DiamondChannelHandle *)array->values[i-target_count].as.object)->channel;
        ChannelWaitRegistration *registration=&registrations[i];
        registration->channel=channel;
        registration->link.write_fd=descriptors[1];
        pthread_mutex_lock(&channel->lock);
        registration->link.next=channel->waiters;
        channel->waiters=&registration->link;
        if(select_drained!=nullptr)
            ready=ready||channel->count>0 ||
                (channel->closed&&!select_drained[i-target_count]);
        else
            ready=ready||channel->closed ||
                (i<target_count&&(writable?channel->count<channel->capacity:channel->count>0));
        pthread_mutex_unlock(&channel->lock);
    }
    /* Trapped signals are dispatched at VM instruction boundaries. Only
     * VMs that installed handlers need a bounded return to that dispatcher;
     * ordinary worker waits have no periodic timeout. EINTR also returns
     * immediately, after unlinking, so handlers can safely close channels. */
    bool signal_aware=false;
    for(size_t i=0;i<DIAMOND_SIGNAL_COUNT;i++)
        if(vm->trapped_signal_handlers[i].kind==DIAMOND_VALUE_OBJECT)
            signal_aware=true;
    int wait_error=0;
    while(!ready) {
        int milliseconds=-1;
        if(timed) {
            struct timespec now;
            if(clock_gettime(CLOCK_MONOTONIC,&now)!=0) {wait_error=errno;break;}
            const double remaining=deadline-(double)now.tv_sec-(double)now.tv_nsec/1e9;
            if(remaining<=0)break;
            const double rounded=ceil(remaining*1000);
            milliseconds=rounded>INT_MAX?INT_MAX:(int)rounded;
        }
        if(signal_aware&&(milliseconds<0||milliseconds>10))milliseconds=10;
        const int result=poll(fds,fd_count+1,milliseconds);
        if(result>0) {
            if(fds[fd_count].revents&(POLLERR|POLLHUP|POLLNVAL))wait_error=EIO;
            break;
        }
        if(result<0) {
            if(errno!=EINTR)wait_error=errno;
            for(nfds_t i=0;i<fd_count;i++)fds[i].revents=0;
            break;
        }
        if(signal_aware)break;
        /* Timeout: recompute against the absolute monotonic deadline.
         * Long deadlines may need more than one INT_MAX-millisecond wait. */
    }
    for(size_t i=0;i<count;i++) {
        ChannelWaitRegistration *registration=&registrations[i];
        pthread_mutex_lock(&registration->channel->lock);
        ChannelWaitLink **link=&registration->channel->waiters;
        while(*link!=&registration->link)link=&(*link)->next;
        *link=registration->link.next;
        pthread_mutex_unlock(&registration->channel->lock);
    }
    close(descriptors[0]);close(descriptors[1]);free(registrations);
    if(wait_error!=0) {
        snprintf(vm->error,sizeof vm->error,"channel wait: %s",strerror(wait_error));
        return DIAMOND_VM_IO_ERROR;
    }
    return DIAMOND_VM_OK;
}

static void free_channel_reference(DiamondChannel *channel);

/* A fixed cap on children per Supervisor, matching DIAMOND_MAX_THREADS/
 * DIAMOND_MAX_ARGUMENTS's own fixed-array style rather than dynamic
 * growth -- see docs/threads.md's Supervisors section. Each child still
 * separately counts against the process-wide DIAMOND_MAX_THREADS budget
 * (one real OS thread per child, for its entire supervised lifetime), so
 * this cap exists to bound one DiamondSupervisor's own fixed-size
 * children[] array, not as an independent resource budget. */
enum { DIAMOND_MAX_SUPERVISOR_CHILDREN = 32 };

typedef struct DiamondSupervisor DiamondSupervisor;

/* One supervised worker slot. `program_template` is cloned exactly once,
 * at add_child time (clone_program_from_chunk -- the same call Thread.new
 * and Channel.new already make), and reused unmodified across every
 * restart of this child: a program's functions/classes/interfaces tables
 * never change once compiled, only the heap data a run against them
 * produces, so there is no need to reclone on every crash the way
 * Thread.new reclones per spawn (a supervised child, unlike a plain
 * Thread, may be spawned/restarted arbitrarily many times over its
 * lifetime -- cloning once amortizes that cost across all of them).
 *
 * `args_vm` exists purely as GC-managed storage for `args[]`, exactly
 * Channel's own private_vm-for-storage trick (src/vm.c's DiamondChannel
 * comment above) -- but write-once, never mutated again after add_child,
 * since supervised args don't change across restarts. `args_vm->
 * extra_roots` is pointed at `args` so args_vm's own occasional GC cycle
 * (triggered only by add_child's own initial copy_value_into_vm calls)
 * keeps them alive. Every restart re-copies from args_vm into that
 * attempt's own fresh run_vm using program_template's classes on both
 * sides -- args_vm and every run_vm are structurally identical clones of
 * the same template, so this is always a same-layout rebase, never a
 * cross-program adopt.
 *
 * `last_error`/`restart_count`/`done` are guarded by the
 * owning DiamondSupervisor's own `lock` (not a per-child lock -- these
 * fields are read rarely, from the one calling thread's own restart_
 * count()/last_error()/alive?() calls, never on any hot path), and
 * written from exactly one place: this child's own dedicated retry-loop
 * OS thread (supervisor_child_entry_trampoline). */
typedef struct DiamondSupervisorChild {
    DiamondProgram *program_template;
    uint16_t function_index;
    DiamondVm *args_vm;
    DiamondValue args[DIAMOND_MAX_ARGUMENTS];
    uint8_t arg_count;
    pthread_t handle;
    DiamondSupervisor *supervisor;
    size_t restart_count;
    /* Same size as DiamondVm.error (src/vm.h) -- last_error is always
     * populated by copying either run_vm->error or format_uncaught_
     * exception_message's own output into it verbatim (supervisor_child_
     * entry_trampoline), so matching that buffer's own size exactly
     * avoids ever truncating it. */
    char last_error[1024];
    /* True once this child's retry loop has permanently stopped running
     * -- either a clean, non-raising return (v1 never restarts on a
     * normal return) or a crash noticed after stop() was called
     * (supervisor_child_entry_trampoline checks stop_requested right
     * after recording a crash, before the next attempt). alive?() is
     * exactly !done. */
    bool done;
    /* Guards against a double pthread_join on this child's own `handle`
     * (undefined behavior per POSIX) -- stop()/join()/free_supervisor_
     * reference are three independent call sites that each join every
     * child, and any combination of them may run against the same
     * Supervisor over its lifetime (stop() then join(), join() called
     * twice, ...). Set under `supervisor->lock` immediately before the
     * actual (unlocked) pthread_join call, mirroring DiamondThread's own
     * `joined` flag/join_lock pairing for the identical reason. */
    bool joined;
    /* Slot index in supervisor->children[], so a crashing child can tell
     * which siblings its strategy reaches. */
    size_t index;
    /* Set (under supervisor->lock) by a crashing sibling when the
     * supervisor's strategy says this child must restart too; polled by
     * this child's own attempt VM (DiamondVm.interrupt_flag) and
     * consumed by its retry loop. Cleared at the start of each attempt,
     * since a fresh attempt is already the restart being asked for. */
    atomic_bool interrupt;
} DiamondSupervisorChild;

/* Restart strategy, chosen once by Supervisor.new(:strategy). Mirrors
 * Erlang's three: only the crashed child (default), every child, or the
 * crashed child and every child added after it. */
typedef enum DiamondSupervisorStrategy {
    DIAMOND_SUPERVISOR_ONE_FOR_ONE,
    DIAMOND_SUPERVISOR_ONE_FOR_ALL,
    DIAMOND_SUPERVISOR_REST_FOR_ONE,
} DiamondSupervisorStrategy;

/* Native backing struct for DiamondSupervisorHandle (object.h) -- see
 * docs/threads.md's Supervisors section and docs/internal/concurrency-
 * internals.md for the full design. Unlike DiamondThread (owned one-to-
 * one) but like DiamondChannel (genuinely shared, refcounted), a
 * Supervisor is refcounted for free-safety consistency even though --
 * see docs/threads.md -- a Supervisor is deliberately not one of
 * copy_value_into_vm's handled kinds, so in practice no second real OS
 * thread can ever obtain a handle to the same Supervisor: `refcount`
 * only ever reaches more than 1 via an ordinary same-heap copy (e.g.
 * storing the same handle in two Array slots), never a cross-thread one.
 *
 * `lock` guards every mutable field below plus each child's own
 * restart_count/last_error/done (DiamondSupervisorChild's
 * own comment). `stop_requested` is a separate lock-free atomic,
 * deliberately not behind `lock`, since every child's retry loop checks
 * it on every single iteration (mirrors DiamondThread's own atomic
 * `finished` -- a hot, lock-free poll is the whole point). */
typedef struct DiamondSupervisor {
    pthread_mutex_t lock;
    atomic_bool stop_requested;
    DiamondSupervisorChild children[DIAMOND_MAX_SUPERVISOR_CHILDREN];
    size_t child_count;
    bool stopped;
    DiamondSupervisorStrategy strategy;
    atomic_size_t refcount;
} DiamondSupervisor;

static void free_supervisor_reference(DiamondSupervisor *supervisor);

static void mark_value(DiamondValue value, bool minor);
static void mark_object(DiamondObject *object, bool minor);
static void mark_frame_chain(void *frames, bool minor);
bool gc_protect(DiamondVm *vm, DiamondValue value);
void gc_unprotect(DiamondVm *vm, size_t saved_count);
static DiamondVmStatus run_chunk(const DiamondChunk *chunk, DiamondVm *vm,
                                 const DiamondValue *arguments,
                                 size_t argument_count, size_t depth,
                                 const DiamondClosure *closure,
                                 DiamondValue *result);
bool hash_set(DiamondVm *vm,DiamondHash *hash,DiamondValue key,
                     DiamondValue value);
bool array_push(DiamondVm *vm,DiamondArray *array,DiamondValue value);
bool numeric_as_double(DiamondValue value, double *out);
static ptrdiff_t hash_find(const DiamondHash *hash,DiamondValue key);
static void free_adopted_programs(void *list);
static void free_thread(DiamondThread *thread);
static void populate_default_argv_env(DiamondVm *vm);
/* diamond_format_value_type itself is declared in vm.h now (exported for
 * src/value.c's own reuse) -- this forward declaration would otherwise
 * conflict with that extern one (mismatched static/extern storage class). */
static void format_uncaught_exception_message(DiamondVm *vm, DiamondValue exception,
                                              bool show_origin);
static DiamondArray *install_backtrace(DiamondVm *vm,DiamondInstance *raised);
static void backtrace_append_live_frames(DiamondVm *vm,DiamondArray *backtrace);
bool copy_value_into_vm(DiamondVm *dest_vm, DiamondValue value,
                               DiamondProgram *source_program,
                               const DiamondClass *rebase_source_classes,
                               const DiamondClass *rebase_dest_classes,
                               const DiamondChunk **adopted_owner,
                               DiamondValue *out);
static void format_operator_type_error(DiamondVm *vm,DiamondValue left_value,
        DiamondValue right_value,const char *op_name);

/* The per-kind "walk this object's own direct children" switch,
 * deliberately factored out of mark_object below (which adds the
 * marked/dead-end guards around it) so mark_remembered_set can call
 * this directly for a remembered root -- see that function's own
 * comment on why it must bypass mark_object's guards specifically for
 * a remembered object's own first level, without duplicating this
 * per-kind logic a second time (every native object kind added over
 * many sessions already has to be listed once here; a second copy
 * would just be one more place for a future kind to be missed from). */
static void mark_object_children(DiamondObject *object, bool minor) {
    if (object->kind == DIAMOND_OBJECT_INSTANCE) {
        DiamondInstance *instance=(DiamondInstance *)object;
        for(size_t i=0;i<instance->field_count;i++) mark_value(instance->fields[i],minor);
    } else if(object->kind==DIAMOND_OBJECT_ARRAY) {
        DiamondArray *array=(DiamondArray *)object;
        for(size_t i=0;i<array->count;i++) mark_value(array->values[i],minor);
    } else if(object->kind==DIAMOND_OBJECT_HASH) {
        DiamondHash *hash=(DiamondHash *)object;
        for(size_t i=0;i<hash->count;i++) {
            mark_value(hash->entries[i].key,minor);
            mark_value(hash->entries[i].value,minor);
        }
    } else if(object->kind==DIAMOND_OBJECT_CLOSURE) {
        DiamondClosure *closure=(DiamondClosure *)object;
        for(size_t i=0;i<closure->capture_count;i++)mark_value(closure->captures[i],minor);
    } else if(object->kind==DIAMOND_OBJECT_CELL) {
        mark_value(((DiamondCell *)object)->value,minor);
    } else if(object->kind==DIAMOND_OBJECT_FIBER) {
        DiamondFiber *fiber=((DiamondFiberHandle *)object)->fiber;
        if(fiber!=nullptr) {
            /* fiber->native_frames is only refreshed when this fiber
             * actually suspends or completes (see diamond_fiber_run) --
             * while it's DIAMOND_FIBER_RUNNING, that field is a stale
             * snapshot from its *previous* suspend, and may by now point at
             * C stack frames that have genuinely already returned (real
             * recursive run_chunk calls unwinding past where they were when
             * that snapshot was taken). A running fiber's actual live
             * frames are already covered elsewhere: diamond_vm_collect's
             * own mark_frame_chain(vm->frames) if it's the innermost
             * running fiber, or an ancestor's own resumer_frames snapshot
             * (also walked there) if it's a fiber blocked resuming a nested
             * child. Every *other* state's native_frames is a safe,
             * up-to-date-enough snapshot -- notably RUNNABLE too, which a
             * fiber scheduler (diamond_fiber_make_runnable) uses for a
             * fiber that just yielded and is waiting for its next turn, not
             * just DIAMOND_FIBER_SUSPENDED. */
            if(fiber->state!=DIAMOND_FIBER_RUNNING)
                mark_frame_chain(fiber->native_frames,minor);
            mark_value(fiber->result,minor);
            mark_value(fiber->resume_value,minor);
            if(fiber->entry_closure!=nullptr)
                mark_object((DiamondObject *)fiber->entry_closure,minor);
        }
    } else if(object->kind==DIAMOND_OBJECT_THREAD) {
        DiamondThread *thread=((DiamondThreadHandle *)object)->thread;
        /* Only once .join() has actually copied `result` into *this*
         * vm's own heap (thread->joined) does it need marking here --
         * before that it lives entirely in child_vm's own, separate heap
         * (this vm's GC has no business scanning another vm's memory),
         * and internal_failure means there's no result value at all (a
         * fresh ThreadError gets built and raised directly at join time
         * instead). See docs/threads.md. */
        if(thread!=nullptr&&thread->joined&&!thread->internal_failure)
            mark_value(thread->result,minor);
    } else if(object->kind==DIAMOND_OBJECT_PROCESS_RESULT) {
        DiamondProcessResult *result=(DiamondProcessResult *)object;
        mark_value(result->stdout_value,minor);
        mark_value(result->stderr_value,minor);
    } else if(object->kind==DIAMOND_OBJECT_PROCESS_HANDLE) {
        DiamondProcessHandle *handle=(DiamondProcessHandle *)object;
        mark_value(handle->stdout_stream,minor);
        mark_value(handle->stderr_stream,minor);
    }
}

/* Marking uses an explicit work stack instead of recursing, so its depth
 * is bounded by heap memory, not by the C stack: a chain of N nested
 * Arrays (or a long linked list of Instances) used to recurse N levels
 * through mark_object -> mark_object_children -> mark_value, and a
 * collection running with a deep enough structure live (a few tens of
 * thousands of levels on a debug build) overflowed the C stack and
 * crashed the process. See the GC issue this fixes in docs/gc-
 * generational-design.md's own notes.
 *
 * thread_local, not per-VM: the mark_* functions take no VM, every Thread
 * runs its own VM's collections on its own OS thread concurrently, and a
 * collection never yields mid-mark (so Fibers sharing one OS thread can't
 * interleave two marks either). mark_roots frees the buffer when its
 * collection ends, so nothing outlives a collection -- no leak when a
 * Thread exits, and no per-mark_object malloc/free churn.
 *
 * `draining` makes the outermost mark_object call the only loop: a nested
 * call (from mark_object_children via mark_value) just marks and pushes.
 * mark_object_children itself is still the single place that knows each
 * object kind's children; this stack deliberately holds every newly
 * marked object (bar Strings/Symbols, which can never have children)
 * rather than duplicating that per-kind list in a "has children"
 * predicate that a future kind could be missed from.
 *
 * If growing the stack fails (out of memory), fall back to the old direct
 * recursion for that object so marking stays correct, just not
 * stack-bounded, exactly as before. */
typedef struct MarkStack {
    DiamondObject **items;
    size_t count;
    size_t capacity;
    bool draining;
} MarkStack;

static thread_local MarkStack diamond_mark_stack;

static void mark_stack_release(void) {
    free(diamond_mark_stack.items);
    diamond_mark_stack=(MarkStack){};
}

static void mark_object(DiamondObject *object, bool minor) {
    if (object == nullptr) return;
    /* A minor collection only traces into the young generation -- an
     * old object reached *during trace* (as opposed to being a
     * remembered-set root, which reaches mark_object_children directly
     * instead of coming through here -- see mark_remembered_set) is a
     * dead end: whatever young objects it points to are already
     * covered by it being a member of the remembered set (or it has
     * none, if nothing was written to it since promotion), so
     * recursing into it here would just redo that same work with no
     * correctness need. See docs/design.md's "Generational garbage
     * collection" section. */
    if (minor && object->old) return;
    if (object->marked) return;
    object->marked = true;
    if (object->kind == DIAMOND_OBJECT_STRING ||
        object->kind == DIAMOND_OBJECT_SYMBOL) return;
    MarkStack *stack = &diamond_mark_stack;
    if (stack->count == stack->capacity) {
        const size_t capacity = stack->capacity == 0 ? 256 : stack->capacity * 2;
        DiamondObject **grown = realloc(stack->items, capacity * sizeof *grown);
        if (grown == nullptr) {
            mark_object_children(object, minor);
            return;
        }
        stack->items = grown;
        stack->capacity = capacity;
    }
    stack->items[stack->count++] = object;
    if (stack->draining) return;
    stack->draining = true;
    while (stack->count > 0)
        mark_object_children(stack->items[--stack->count], minor);
    stack->draining = false;
}

static void mark_value(DiamondValue value, bool minor) {
    if (value.kind == DIAMOND_VALUE_OBJECT) mark_object(value.as.object, minor);
}

static void mark_frame_chain(void *frames, bool minor) {
    for (DiamondFrame *frame = frames; frame != nullptr;
         frame = frame->previous) {
        for (size_t index = 0; index < frame->register_count; index++) {
            mark_value(frame->registers[index], minor);
        }
        if(frame->pending!=nullptr && frame->pending->kind!=PENDING_NONE)
            mark_value(frame->pending->value, minor);
        if(frame->handlers!=nullptr && frame->handler_count!=nullptr)
            for(size_t i=0;i<*frame->handler_count;i++)
                if(frame->handlers[i].kind==HANDLER_ACTIVE_ENSURE)
                    mark_value(frame->handlers[i].saved_pending.value,minor);
    }
}

static void mark_fiber(const DiamondFiber *fiber, bool minor) {
    if (fiber == nullptr) return;
    /* Same staleness hazard as mark_object's DIAMOND_OBJECT_FIBER case
     * above: native_frames is only untrustworthy while this exact fiber is
     * the one currently RUNNING. */
    if (fiber->state != DIAMOND_FIBER_RUNNING)
        mark_frame_chain(fiber->native_frames, minor);
}

/* Every entry in vm->remembered_set (see that field's own comment in
 * vm.h) is an *old* object -- calls mark_object_children directly
 * rather than mark_object, deliberately bypassing both of that
 * function's guards for exactly this one call: the "dead end at an
 * old object" rule exists to stop recursion reaching an old object
 * *transitively* during trace, which must not also block scanning a
 * remembered root's own children (the entire reason it's in the
 * remembered set); and the "already marked" rule is meaningless here
 * since a minor collection never sets `marked` on an old object at
 * all (mark_object's own guard returns before ever reaching that
 * line), so it would always read false anyway.
 *
 * Array/Hash are special-cased to scan only their dirty cards (see
 * mark_card_dirty/gc_write_barrier_index above) instead of every
 * element -- this is the actual Phase 4 fix: the first generational
 * attempt remembered these two kinds at whole-container granularity,
 * which meant re-walking a large, mostly-stable container on *every*
 * minor collection it survived. A card is cleared once scanned (a
 * later write re-dirties it for the next pass); dirty_cards==nullptr
 * means no index write has happened since promotion (or since the last
 * full scan created it), so there's nothing to walk. Falls back to a
 * full mark_object_children scan if dirty_cards is somehow null on an
 * object already in the remembered set (should never happen, since
 * only gc_write_barrier_index/_range ever call remember() on these two
 * kinds, and both always mark a card immediately after -- but a missed
 * scan here would silently free a live young value, so this defaults
 * to the safe side rather than skipping). */
static void mark_remembered_set(DiamondVm *vm) {
    for (size_t index = 0; index < vm->remembered_count; index++) {
        DiamondObject *object = vm->remembered_set[index];
        if (object->kind == DIAMOND_OBJECT_ARRAY) {
            DiamondArray *array = (DiamondArray *)object;
            if (array->dirty_cards == nullptr) {
                mark_object_children(object, true);
                continue;
            }
            const size_t card_count =
                (array->capacity + DIAMOND_GC_CARD_SIZE - 1) / DIAMOND_GC_CARD_SIZE;
            for (size_t card = 0;
                 card < card_count && card < array->dirty_card_capacity; card++) {
                if (!array->dirty_cards[card]) continue;
                const size_t start = card * DIAMOND_GC_CARD_SIZE;
                const size_t end = start + DIAMOND_GC_CARD_SIZE < array->count ?
                    start + DIAMOND_GC_CARD_SIZE : array->count;
                for (size_t i = start; i < end; i++) mark_value(array->values[i], true);
                array->dirty_cards[card] = 0;
            }
        } else if (object->kind == DIAMOND_OBJECT_HASH) {
            DiamondHash *hash = (DiamondHash *)object;
            if (hash->dirty_cards == nullptr) {
                mark_object_children(object, true);
                continue;
            }
            const size_t card_count =
                (hash->capacity + DIAMOND_GC_CARD_SIZE - 1) / DIAMOND_GC_CARD_SIZE;
            for (size_t card = 0;
                 card < card_count && card < hash->dirty_card_capacity; card++) {
                if (!hash->dirty_cards[card]) continue;
                const size_t start = card * DIAMOND_GC_CARD_SIZE;
                const size_t end = start + DIAMOND_GC_CARD_SIZE < hash->count ?
                    start + DIAMOND_GC_CARD_SIZE : hash->count;
                for (size_t i = start; i < end; i++) {
                    mark_value(hash->entries[i].key, true);
                    mark_value(hash->entries[i].value, true);
                }
                hash->dirty_cards[card] = 0;
            }
        } else {
            mark_object_children(object, true);
        }
    }
}

/* Defined near DiamondAdoptedProgram itself (this function is used
 * before that type is declared) -- marks every compile_method
 * bound_value kept alive in vm->adopted_programs, the one place this
 * whole feature needs the collector's help (everything else it added --
 * DiamondClosure.foreign_chunk, DiamondMethod.source_chunk -- is a
 * non-owning reference to something else's already-covered lifetime).
 * A no-op for a ProgramBuilder-only adoption (bound_value_count==0). */
static void mark_adopted_programs(void *list, bool minor);

/* The complete root set, minus the remembered set -- shared by both
 * major (minor=false) and minor (minor=true) collection, since a
 * minor collection's own roots are exactly this same walk plus every
 * remembered-set entry (mark_remembered_set, appended at the end when
 * minor is true). Every mark_* call below threads `minor` through so
 * mark_object's own generational dead-end guard applies consistently
 * regardless of which collection triggered this walk. */
static void mark_roots(DiamondVm *vm, bool minor) {
    if(vm->has_exception)mark_value(vm->exception,minor);
    mark_value(vm->nonlocal_value,minor);
    mark_adopted_programs(vm->adopted_programs,minor);
    mark_value(vm->argv_value,minor);
    mark_value(vm->env_value,minor);
    for(size_t index=0;index<vm->gc_protected_count;index++)
        mark_value(vm->gc_protected[index],minor);
    for(size_t index=0;index<DIAMOND_MAX_NAMESPACE_CONSTANTS;index++)
        if(vm->namespace_constant_initialized[index])
            mark_value(vm->namespace_constants[index],minor);
    /* Never allocated (see class_variables' own comment in vm.h) until
     * the first SET_CVAR -- nothing to mark if no class variable has
     * ever been written on this VM. Once allocated, no initialized
     * bitmap to gate individual slots on either: every never-assigned
     * slot is just DIAMOND_NIL (calloc's own zero-fill), and mark_value
     * on a nil is already a same-cost no-op check, so marking the full
     * flat array unconditionally costs nothing extra over tracking real
     * per-class counts here would. */
    if(vm->class_variables!=nullptr)
        for(size_t index=0;index<(size_t)DIAMOND_MAX_CLASSES*DIAMOND_MAX_FIELDS;index++)
            mark_value(vm->class_variables[index],minor);
    for(size_t index=0;index<DIAMOND_SIGNAL_COUNT;index++)
        mark_value(vm->trapped_signal_handlers[index],minor);
    mark_frame_chain(vm->frames,minor);
    for (DiamondFiber *ancestor = vm->running_fiber; ancestor != nullptr;
         ancestor = ancestor->resumer_fiber)
        mark_frame_chain(ancestor->resumer_frames,minor);
    if (vm->root_queue != nullptr)
        for (size_t index = 0; index < diamond_fiber_queue_count(vm->root_queue); index++)
            mark_fiber(diamond_fiber_queue_at(vm->root_queue, index),minor);
    for(size_t index=0;index<vm->extra_root_count;index++)
        mark_value(vm->extra_roots[index],minor);
    if (minor) mark_remembered_set(vm);
    mark_stack_release();
}

/* Sweeps *list_head, freeing anything left unmarked exactly as the
 * single-generation collector always did (the per-kind cleanup switch
 * below is unchanged from before the generational split -- factored
 * out here so major collection, over both young_objects and
 * old_objects, and minor collection, over young_objects alone, share
 * one copy instead of drifting two independent ones as new native
 * object kinds keep getting added). A survivor (still marked) either
 * stays in *list_head with its mark bit reset (promote_to==nullptr --
 * major collection: it's already exactly where it belongs, in whichever
 * generation it was already in), or is spliced onto *promote_to instead
 * with `old` set true (promote_to!=nullptr -- minor collection
 * promoting a young survivor: unlink from young_objects, relink onto
 * old_objects, no copy -- see docs/design.md's "Generational garbage
 * collection" section on why this is safe and needs no age counter for
 * a non-moving collector). */
static void sweep_list(DiamondVm *vm, DiamondObject **list_head,
        DiamondObject **promote_to) {
    DiamondObject **object = list_head;
    while (*object != nullptr) {
        if ((*object)->marked) {
            (*object)->marked = false;
            if (promote_to != nullptr) {
                DiamondObject *survivor = *object;
                *object = survivor->next;
                survivor->old = true;
                survivor->next = *promote_to;
                *promote_to = survivor;
                continue;
            }
            object = &(*object)->next;
            continue;
        }
        DiamondObject *unreached = *object;
        *object = unreached->next;
        size_t size=sizeof(DiamondObject);
        if(unreached->kind==DIAMOND_OBJECT_STRING) {
            const DiamondString *string=(const DiamondString *)unreached;
            size=sizeof(DiamondString)+string->length+1;
        } else if(unreached->kind==DIAMOND_OBJECT_INSTANCE) {
            const DiamondInstance *instance=(const DiamondInstance *)unreached;
            size=sizeof(DiamondInstance)+instance->field_count*sizeof(DiamondValue);
        } else if(unreached->kind==DIAMOND_OBJECT_ARRAY) {
            DiamondArray *array=(DiamondArray *)unreached;
            size=sizeof(DiamondArray)+array->capacity*sizeof(DiamondValue);
            for(size_t index=0;index<array->constraint_count;index++)
                free(array->constraints[index].type_variable_bindings);
            free(array->values);free(array->dirty_cards);
        } else if(unreached->kind==DIAMOND_OBJECT_HASH) {
            DiamondHash *hash=(DiamondHash *)unreached;
            size=sizeof(DiamondHash)+hash->capacity*sizeof(DiamondHashEntry)+
                hash->bucket_capacity*sizeof(size_t);
            for(size_t index=0;index<hash->constraint_count;index++)
                free(hash->constraints[index].type_variable_bindings);
            free(hash->entries);free(hash->buckets);free(hash->dirty_cards);
        } else if(unreached->kind==DIAMOND_OBJECT_CLOSURE) {
            size=sizeof(DiamondClosure);
        } else if(unreached->kind==DIAMOND_OBJECT_FIBER) {
            size=sizeof(DiamondFiberHandle);
            diamond_fiber_free(((DiamondFiberHandle *)unreached)->fiber);
        } else if(unreached->kind==DIAMOND_OBJECT_FILE) {
            size=sizeof(DiamondFileHandle);
            FILE *stream=((DiamondFileHandle *)unreached)->stream;
            if(stream!=nullptr)fclose(stream);
        } else if(unreached->kind==DIAMOND_OBJECT_LISTENER) {
            size=sizeof(DiamondListenerHandle);
            DiamondListenerHandle *listener=(DiamondListenerHandle *)unreached;
            if(listener->fd>=0)close(listener->fd);
            if(listener->tls_context!=nullptr)SSL_CTX_free(listener->tls_context);
            free(listener->alpn_protocols);
        } else if(unreached->kind==DIAMOND_OBJECT_SOCKET) {
            size=sizeof(DiamondSocketHandle);
            const int fd=((DiamondSocketHandle *)unreached)->fd;
            if(fd>=0)close(fd);
        } else if(unreached->kind==DIAMOND_OBJECT_UDP_SOCKET) {
            size=sizeof(DiamondUdpSocketHandle);
            const int fd=((DiamondUdpSocketHandle *)unreached)->fd;
            if(fd>=0)close(fd);
        } else if(unreached->kind==DIAMOND_OBJECT_TLS_SOCKET) {
            size=sizeof(DiamondTlsSocketHandle);
            DiamondTlsSocketHandle *tls_handle=(DiamondTlsSocketHandle *)unreached;
            if(tls_handle->ssl!=nullptr) {
                if(!tls_handle->handshake_pending)SSL_shutdown(tls_handle->ssl);
                SSL_free(tls_handle->ssl);
            }
            if(tls_handle->fd>=0)close(tls_handle->fd);
            if(tls_handle->received_session!=nullptr)
                SSL_SESSION_free(tls_handle->received_session);
        } else if(unreached->kind==DIAMOND_OBJECT_BIGNUM) {
            const DiamondBignum *bignum=(const DiamondBignum *)unreached;
            size=sizeof(DiamondBignum)+bignum->limb_count*sizeof(uint32_t);
        } else if(unreached->kind==DIAMOND_OBJECT_SYMBOL) {
            const DiamondSymbol *symbol=(const DiamondSymbol *)unreached;
            size=sizeof(DiamondSymbol)+symbol->length+1;
        } else if(unreached->kind==DIAMOND_OBJECT_REGEXP) {
            size=sizeof(DiamondRegexp);
            reginold_regex_free(((DiamondRegexp *)unreached)->handle);
        } else if(unreached->kind==DIAMOND_OBJECT_PROGRAM_BUILDER) {
            size=sizeof(DiamondProgramBuilder)+sizeof(DiamondProgram);
            DiamondProgramBuilder *builder=(DiamondProgramBuilder *)unreached;
            if(builder->source_bundle!=nullptr) {
                diamond_source_bundle_free(builder->source_bundle);
                free(builder->source_bundle);
            }
            diamond_program_free(builder->program);
            free(builder->program);
        } else if(unreached->kind==DIAMOND_OBJECT_THREAD) {
            size=sizeof(DiamondThreadHandle);
            free_thread(((DiamondThreadHandle *)unreached)->thread);
        } else if(unreached->kind==DIAMOND_OBJECT_CHANNEL) {
            size=sizeof(DiamondChannelHandle);
            free_channel_reference(((DiamondChannelHandle *)unreached)->channel);
        } else if(unreached->kind==DIAMOND_OBJECT_SUPERVISOR) {
            size=sizeof(DiamondSupervisorHandle);
            free_supervisor_reference(
                ((DiamondSupervisorHandle *)unreached)->supervisor);
        } else if(unreached->kind==DIAMOND_OBJECT_SQLITE3) {
            size=sizeof(DiamondSqlite3Handle);
            sqlite3 *db=((DiamondSqlite3Handle *)unreached)->db;
            /* _v2, not plain sqlite3_close: a Statement prepared from this
             * connection (SQLite3#prepare) can outlive the connection's own
             * Diamond-level reachability -- an independent GC object with no
             * back-reference forcing sweep order between the two. Plain
             * sqlite3_close fails (SQLITE_BUSY, unclosed) with any
             * unfinalized statement still outstanding, and this call site
             * never checked that return code, so it would silently leak the
             * real OS-level connection. _v2 never fails: it closes
             * immediately if nothing is outstanding, or defers the actual
             * close until every associated statement is itself finalized
             * (already guaranteed by the SQLITE3_STATEMENT branch just
             * below, and by Statement#close) -- sqlite3's own documented
             * idiom for exactly this ownership shape. */
            if(db!=nullptr)sqlite3_close_v2(db);
        } else if(unreached->kind==DIAMOND_OBJECT_SQLITE3_STATEMENT) {
            size=sizeof(DiamondSqlite3StatementHandle);
            sqlite3_stmt *stmt=((DiamondSqlite3StatementHandle *)unreached)->stmt;
            if(stmt!=nullptr)sqlite3_finalize(stmt);
        } else if(unreached->kind==DIAMOND_OBJECT_POSTGRES) {
            size=sizeof(DiamondPostgresHandle);
            PGconn *conn=((DiamondPostgresHandle *)unreached)->conn;
            if(conn!=nullptr)PQfinish(conn);
        } else if(unreached->kind==DIAMOND_OBJECT_MYSQL) {
            size=sizeof(DiamondMysqlHandle);
            MYSQL *conn=((DiamondMysqlHandle *)unreached)->conn;
            if(conn!=nullptr)mysql_close(conn);
        } else if(unreached->kind==DIAMOND_OBJECT_TIME) {
            /* No owned resource, no separate allocation -- free(unreached)
             * below is all that's needed; this branch exists only for
             * accurate bytes_allocated accounting. */
            size=sizeof(DiamondTime);
        } else if(unreached->kind==DIAMOND_OBJECT_PROCESS_RESULT) {
            /* Same as DIAMOND_OBJECT_TIME above: no owned OS resource by
             * this point (process_run_helper already closed both pipes
             * and reaped the child before ever returning), no separate
             * allocation -- just accounting. */
            size=sizeof(DiamondProcessResult);
        } else if(unreached->kind==DIAMOND_OBJECT_PROCESS_STREAM) {
            size=sizeof(DiamondProcessStream);
            const int fd=((DiamondProcessStream *)unreached)->fd;
            if(fd>=0)close(fd);
        } else if(unreached->kind==DIAMOND_OBJECT_PROCESS_HANDLE) {
            size=sizeof(DiamondProcessHandle);
            /* Non-blocking reap only -- a handle the caller dropped
             * without ever calling #wait must not stall this GC pass on
             * some unrelated, possibly long-lived child. If the child
             * hasn't exited yet, it's simply left running, detached from
             * any Diamond-level handle from this point on (same as a
             * shell backgrounding a job and then exiting) -- not
             * reachable for #wait/#kill any more, but not killed either.
             * If it already exited, this reaps it so it doesn't sit
             * around as a zombie forever just because nothing ever
             * called #wait/#running? on its own handle. */
            DiamondProcessHandle *handle=(DiamondProcessHandle *)unreached;
            if(!handle->reaped) {
                int reap_status=0;
                pid_t reap_result=0;
                do {reap_result=waitpid(handle->pid,&reap_status,WNOHANG);}
                while(reap_result<0&&errno==EINTR);
            }
        } else if(unreached->kind==DIAMOND_OBJECT_TENSOR) {
            /* No owned OS resource, no separate allocation -- payload is
             * the struct's own flexible array member, one malloc, freed
             * by the generic free(unreached) below. This branch exists
             * only for accurate bytes_allocated accounting, same as
             * DIAMOND_OBJECT_TIME's own. */
            const DiamondTensor *tensor=(const DiamondTensor *)unreached;
            size=sizeof(DiamondTensor)+tensor->rows*tensor->cols*sizeof(double);
        } else {
            size=sizeof(DiamondCell);
        }
        vm->bytes_allocated -= size;
        free(unreached);
    }
}

/* Adds `owner` to vm->remembered_set if it isn't already there -- see
 * DiamondObject.remembered's own comment for why the caller
 * (gc_write_barrier) only ever calls this once per object's lifetime as
 * an old object. Grows like gc_protected (the closest existing
 * precedent in this file) -- doubling capacity, never shrinks. Returns
 * false only on allocation failure. */
static bool remember(DiamondVm *vm, DiamondObject *owner) {
    if (vm->remembered_count == vm->remembered_capacity) {
        const size_t grown_capacity =
            vm->remembered_capacity == 0 ? 16 : vm->remembered_capacity * 2;
        DiamondObject **grown =
            realloc(vm->remembered_set, grown_capacity * sizeof *grown);
        if (grown == nullptr) return false;
        vm->remembered_set = grown;
        vm->remembered_capacity = grown_capacity;
    }
    vm->remembered_set[vm->remembered_count++] = owner;
    return true;
}

/* The write barrier -- called at every mutation site that stores a
 * value into an already-allocated container/object (see docs/gc-
 * generational-design.md's own audited-sites list; re-verified fresh
 * against current code rather than trusted, since that document's own
 * line numbers are already stale -- src/vm.c's own call sites are the
 * up-to-date authority). Only old->young writes matter: a minor
 * collection's ordinary root walk already sees anything reachable
 * *from* a young object directly (young_objects is swept every minor
 * pass regardless), so this only needs to record the one case that
 * walk wouldn't otherwise catch -- an *old* object gaining a pointer to
 * a young one. Unconditional on the stored value's own generation (or
 * even whether it's an object at all) -- a cheaper branch than checking,
 * over-remembers old->old writes and non-object values, an accepted
 * tradeoff matching the retained design's own reasoning. Returns false
 * only when growing the remembered set failed (remember's own return
 * value) -- callers propagate that as DIAMOND_VM_OUT_OF_MEMORY exactly
 * like any other allocation failure at the same call site, rather than
 * risk silently under-recording a live old->young edge. */
bool gc_write_barrier(DiamondVm *vm, DiamondObject *owner) {
    if (owner->old && !owner->remembered) {
        if (!remember(vm, owner)) return false;
        owner->remembered = true;
    }
    return true;
}

/* Marks the card containing `index` dirty on an old Array or Hash,
 * lazily allocating (or growing) the card table to cover the object's
 * current capacity if needed -- most old Array/Hash objects are never
 * index-written again after promotion, so this stays unallocated in the
 * common case rather than being sized up front for every promotion.
 * Only ever called (via gc_write_barrier_index/_range below) after the
 * caller has already confirmed `owner` is old, so it doesn't re-check
 * that itself. Deliberately not counted in vm->bytes_allocated (unlike
 * values/entries/buckets, which every realloc site already tracks) --
 * a handful of cards is negligible next to the container it shadows
 * (~625 bytes for a 40,000-entry Hash), not worth a second accounting
 * path for. Returns false only on allocation failure. */
/* DiamondArray and DiamondHash lay out dirty_cards/dirty_card_capacity at
 * different offsets (object.h) -- fine at runtime, since owner->kind
 * always picks the matching branch below, but when this function gets
 * inlined at -O3 into a call site where the concrete object is
 * statically known to be one specific (smaller) allocation size, e.g.
 * diamond_vm_set_argv's own Array-only construction, GCC's -Warray-bounds
 * still evaluates the *other*, provably-unreachable-there branch's
 * hash->dirty_cards/hash->capacity access against that size and reports
 * a false positive. Confirmed false: the two branches are never
 * conflated at runtime, only during this particular inlined analysis. */
#if defined(__GNUC__)
#pragma GCC diagnostic push
#pragma GCC diagnostic ignored "-Warray-bounds"
#endif
static bool mark_card_dirty(DiamondObject *owner, size_t index) {
    uint8_t **dirty_cards;size_t *dirty_card_capacity,capacity;
    if(owner->kind==DIAMOND_OBJECT_ARRAY) {
        DiamondArray *array=(DiamondArray *)owner;
        dirty_cards=&array->dirty_cards;
        dirty_card_capacity=&array->dirty_card_capacity;
        capacity=array->capacity;
    } else {
        DiamondHash *hash=(DiamondHash *)owner;
        dirty_cards=&hash->dirty_cards;
        dirty_card_capacity=&hash->dirty_card_capacity;
        capacity=hash->capacity;
    }
    const size_t needed_cards=
        (capacity+DIAMOND_GC_CARD_SIZE-1)/DIAMOND_GC_CARD_SIZE;
    if(*dirty_cards==nullptr) {
        const size_t initial=needed_cards==0?1:needed_cards;
        uint8_t *fresh=calloc(initial,1);
        if(fresh==nullptr)return false;
        *dirty_cards=fresh;*dirty_card_capacity=initial;
    } else if(needed_cards>*dirty_card_capacity) {
        uint8_t *grown=realloc(*dirty_cards,needed_cards);
        if(grown==nullptr)return false;
        memset(grown+*dirty_card_capacity,0,needed_cards-*dirty_card_capacity);
        *dirty_cards=grown;*dirty_card_capacity=needed_cards;
    }
    (*dirty_cards)[index/DIAMOND_GC_CARD_SIZE]=1;
    return true;
}
#if defined(__GNUC__)
#pragma GCC diagnostic pop
#endif

/* gc_write_barrier's own Array/Hash-specific sibling: same old-object/
 * remembered-set bookkeeping, plus marking the one card the write
 * actually touched dirty (see mark_card_dirty above) so
 * mark_remembered_set (below) can scan just that card on the next minor
 * collection instead of the whole container. */
static bool gc_write_barrier_index(DiamondVm *vm, DiamondObject *owner, size_t index) {
    if (!owner->old) return true;
    if (!owner->remembered) {
        if (!remember(vm, owner)) return false;
        owner->remembered = true;
    }
    return mark_card_dirty(owner, index);
}

/* gc_write_barrier_index's range-write sibling (DIAMOND_OP_INDEX_SET's
 * Array range-assignment branch) -- dirties every card touched by
 * [start, start+count). */
static bool gc_write_barrier_range(DiamondVm *vm, DiamondObject *owner,
        size_t start, size_t count) {
    if (!owner->old) return true;
    if (!owner->remembered) {
        if (!remember(vm, owner)) return false;
        owner->remembered = true;
    }
    if (count == 0) return true;
    const size_t first_card = start / DIAMOND_GC_CARD_SIZE;
    const size_t last_card = (start + count - 1) / DIAMOND_GC_CARD_SIZE;
    for (size_t card = first_card; card <= last_card; card++)
        if (!mark_card_dirty(owner, card * DIAMOND_GC_CARD_SIZE)) return false;
    return true;
}

static void diamond_vm_collect_impl(DiamondVm *vm) {
    mark_roots(vm, false);
    /* Filter the remembered set by `marked` *before* sweeping below --
     * an entry whose object didn't get marked by the full pass above is
     * genuinely unreachable and about to be freed by the sweep; keeping
     * it here would leave vm->remembered_set holding a dangling pointer
     * once that happens. Confirmed as a real use-after-free during the
     * first implementation attempt at this design, not just a
     * theoretical concern -- see docs/gc-generational-design.md. A
     * surviving old object's own `remembered` bit needs no change here:
     * whatever young object it still points to was necessarily also
     * marked by this same full, unrestricted major pass, so it survives
     * the sweep below too. */
    size_t kept_remembered = 0;
    for (size_t index = 0; index < vm->remembered_count; index++)
        if (vm->remembered_set[index]->marked)
            vm->remembered_set[kept_remembered++] = vm->remembered_set[index];
    vm->remembered_count = kept_remembered;
    sweep_list(vm, &vm->young_objects, nullptr);
    sweep_list(vm, &vm->old_objects, nullptr);
    vm->next_gc = vm->bytes_allocated < 1024
        ? 2048 : vm->bytes_allocated * 2;
    vm->bytes_allocated_at_last_minor_gc = vm->bytes_allocated;
}

/* The minor collector: traces only into the young generation (roots
 * plus the remembered set -- mark_roots(vm,true) covers both), sweeps
 * only vm->young_objects, and promotes every survivor straight onto
 * vm->old_objects (sweep_list's own promote_to parameter) rather than
 * leaving it in place. Deliberately does *not* touch vm->remembered_set
 * at all -- a minor collection never discovers a *dead* old object
 * (old_objects is never swept here), so there is nothing to filter;
 * only a major collection's full liveness pass over the old generation
 * can determine that, which is exactly why the remembered-set filtering
 * lives in diamond_vm_collect_impl instead. */
static void diamond_vm_collect_minor_impl(DiamondVm *vm) {
    mark_roots(vm, true);
    sweep_list(vm, &vm->young_objects, &vm->old_objects);
    vm->bytes_allocated_at_last_minor_gc = vm->bytes_allocated;
}

/* Timing wrapper around diamond_vm_collect_impl (the major collector)
 * -- see vm.h's own comment on gc_major_collection_count/
 * gc_major_total_seconds for why this exists (DIAMOND_TRACE_GC,
 * src/run_source.c). CLOCK_MONOTONIC, matching every other wall-time
 * measurement in this file (Time.monotonic(), the TCP/TLS/UDP retry-
 * loop deadline checks) -- immune to wall-clock adjustments, which a
 * long-running collection-heavy process is exactly the kind of thing
 * that could otherwise run across. */
void diamond_vm_collect(DiamondVm *vm) {
    struct timespec start={};
    clock_gettime(CLOCK_MONOTONIC,&start);
    diamond_vm_collect_impl(vm);
    struct timespec end={};
    clock_gettime(CLOCK_MONOTONIC,&end);
    vm->gc_major_collection_count++;
    vm->gc_major_total_seconds+=
        (double)(end.tv_sec-start.tv_sec)+
        (double)(end.tv_nsec-start.tv_nsec)/1e9;
}

/* Same timing wrapper, over diamond_vm_collect_minor_impl instead --
 * see vm.h's own comment on gc_minor_collection_count/
 * gc_minor_total_seconds. Public (not static), matching
 * diamond_vm_collect's own visibility, so a test can force a
 * deterministic minor collection directly the same way several existing
 * tests already call diamond_vm_collect (tests/fiber_run.c). */
void diamond_vm_collect_minor(DiamondVm *vm) {
    struct timespec start={};
    clock_gettime(CLOCK_MONOTONIC,&start);
    diamond_vm_collect_minor_impl(vm);
    struct timespec end={};
    clock_gettime(CLOCK_MONOTONIC,&end);
    vm->gc_minor_collection_count++;
    vm->gc_minor_total_seconds+=
        (double)(end.tv_sec-start.tv_sec)+
        (double)(end.tv_nsec-start.tv_nsec)/1e9;
}

/* The single collection-trigger check every allocate_* helper in this
 * file makes before actually allocating -- originally factored out of
 * 23 previously-duplicated inline copies (confirmed by direct grep, not
 * assumed) so a generational collector's own cheaper, more-frequent
 * minor-GC threshold would have exactly one place to be added, instead
 * of needing to touch all 23 call sites again -- and now that place.
 * Minor checked first (cheaper, fires far more often); major checked
 * unconditionally after, in case a lot of the nursery just got promoted
 * and total live bytes are already past next_gc too.
 *
 * Also the one place a configured DIAMOND_MAX_MEMORY_BYTES budget
 * (docs/sandbox.md's own "Resource limits" section) is enforced -- exactly
 * this comment's own "exactly one place to be added" reasoning, extended
 * to a second kind of limit. Returns false (checked after both collection
 * passes above already ran, giving them a real chance to free memory
 * first) once live bytes are still over budget; every one of this
 * function's own callers already has a `return nullptr`/`return false`
 * OOM path one line below its own `malloc`/`calloc` check, and reuses that
 * exact path here rather than a new error shape -- see this status's own
 * comment in vm.h for why this deliberately reuses DIAMOND_VM_OUT_OF_
 * MEMORY rather than a new status.
 *
 * Clears max_memory_bytes (disabling this check for the rest of the VM's
 * lifetime) the *first* time it actually fires, for the same reason
 * DIAMOND_MAX_INSTRUCTIONS/DIAMOND_MAX_WALL_MILLISECONDS clear themselves
 * in run_chunk's own dispatch loop: catch_runtime_error's own path to
 * report this failure as a real, rescuable OutOfMemoryError itself calls
 * allocate_instance/allocate_string, which would call straight back into
 * this same function -- if bytes_allocated is still (deliberately) over
 * budget, leaving the check armed would make it return false again there
 * too, making the exception impossible to ever construct, let alone
 * rescue. Once the budget has genuinely been exceeded once, further
 * allocation needed just to report and unwind that fact is let through. */
bool maybe_collect(DiamondVm *vm) {
    if(vm->stress_minor_gc||
       vm->bytes_allocated-vm->bytes_allocated_at_last_minor_gc>=vm->minor_gc_threshold_bytes)
        diamond_vm_collect_minor(vm);
    if(vm->stress_gc||vm->bytes_allocated>=vm->next_gc)diamond_vm_collect(vm);
    if(vm->max_memory_bytes!=0&&vm->bytes_allocated>vm->max_memory_bytes) {
        vm->max_memory_bytes=0;
        vm->memory_limit_tripped=true;
        return false;
    }
    return true;
}

/* mysql_init() -- called per-connection from MySQL.open's dispatch --
 * implicitly runs mysql_library_init() the first time it's ever called
 * in the process if nothing already called it explicitly. That implicit
 * path is documented by the MySQL/MariaDB client library as unsafe under
 * concurrent first use: two threads racing their first MySQL.open at once
 * can corrupt the client library's own one-time setup. Diamond threads are
 * independent OS threads with isolated heaps (see docs/threads.md) that can
 * each reach MySQL.open before any other thread has, so an explicit,
 * pthread_once-guarded call here -- once per process, from every VM's own
 * init, the same "once per VM, idempotent" shape as the SIGPIPE handling
 * below -- removes the race instead of relying on the implicit path. */
static pthread_once_t mysql_library_init_once = PTHREAD_ONCE_INIT;

void diamond_vm_init(DiamondVm *vm) {
    *vm = (DiamondVm){.next_gc = 2048,.range_class_index=UINT8_MAX,
        .minor_gc_threshold_bytes = 1048576,.debug_fd=-1};
    vm->quickening_threshold = 1;
    vm->monomorphic_threshold = 1;
    /* Much higher than quickening_threshold's 1: an opcode rewrite is a
     * single in-place byte write, while a JIT compile allocates and fills
     * a whole executable-memory buffer -- worth doing only for a function
     * that's actually going to be called a lot, not the first handful of
     * calls. Unmeasured beyond "clearly should not be 1"; see
     * docs/internal/jit-design.md. */
    vm->jit_threshold = 50;
    /* See DiamondVm.debug_fd's own comment (src/vm.h): read once here,
     * not per-pause. An unparseable or negative value is treated the
     * same as unset -- debugger_helper's ordinary stdout/stdin path --
     * rather than failing VM init over a malformed env var. */
    const char *debug_fd_env=getenv("DIAMOND_DEBUG_FD");
    if(debug_fd_env!=nullptr) {
        const long parsed=strtol(debug_fd_env,nullptr,10);
        if(parsed>=0&&parsed<=INT_MAX)vm->debug_fd=(int)parsed;
    }
    /* Initial breakpoint positions (see DiamondVm.debug_active_lines's own
     * comment above): the initial armed set, read directly here rather
     * than threaded in as a parameter, matching debug_fd's own
     * independent-per-VM env read just above. A live `setBreakpoints`
     * command (docs/debugging.md) freely replaces this later -- this is
     * only ever the *starting* point, and may legitimately be empty
     * (comma-separated, same convention as every other DIAMOND_*-env-var
     * list elsewhere in this codebase; malformed entries are skipped
     * rather than failing VM init, matching debug_fd's own tolerance). */
    const char *debug_breakpoints_env=getenv("DIAMOND_DEBUG_BREAKPOINT_OFFSETS");
    vm->debug_breakpoints_are_offsets=debug_breakpoints_env!=nullptr;
    if(debug_breakpoints_env==nullptr)
        debug_breakpoints_env=getenv("DIAMOND_DEBUG_BREAKPOINTS");
    if(debug_breakpoints_env!=nullptr) {
        const char *cursor=debug_breakpoints_env;
        while(*cursor!='\0'&&vm->debug_active_line_count<DIAMOND_MAX_ACTIVE_BREAKPOINTS) {
            while(*cursor==' '||*cursor==',')cursor++;
            if(*cursor=='\0')break;
            char *end=nullptr;
            const unsigned long long parsed=strtoull(cursor,&end,10);
            if(end==cursor)break;
            vm->debug_active_lines[vm->debug_active_line_count++]=(size_t)parsed;
            cursor=end;
        }
    }
    /* Resource limits (docs/sandbox.md's own "Resource limits" section) --
     * DiamondVm.max_instructions/max_wall_nanoseconds/max_memory_bytes's
     * own comment (src/vm.h) explains why this is read once per VM here
     * rather than a process-wide cache: every VM (this one, a spawned
     * Thread's child_vm, a Supervisor child's run_vm, ProgramBuilder#run's
     * own run_vm) independently reads the same real process environment
     * at its own init, matching DIAMOND_SANDBOX's own propagation-free
     * design. An unparseable, zero, or negative value is treated the same
     * as unset (no limit), matching debug_fd's own convention just above. */
    const char *max_instructions_env=getenv("DIAMOND_MAX_INSTRUCTIONS");
    if(max_instructions_env!=nullptr&&max_instructions_env[0]!='\0') {
        char *end=nullptr;
        const unsigned long long parsed=strtoull(max_instructions_env,&end,10);
        if(end!=max_instructions_env&&*end=='\0'&&parsed>0&&parsed<=SIZE_MAX)
            vm->max_instructions=(size_t)parsed;
    }
    const char *max_wall_env=getenv("DIAMOND_MAX_WALL_MILLISECONDS");
    if(max_wall_env!=nullptr&&max_wall_env[0]!='\0') {
        char *end=nullptr;
        const unsigned long long parsed=strtoull(max_wall_env,&end,10);
        if(end!=max_wall_env&&*end=='\0'&&parsed>0&&
           parsed<=(unsigned long long)INT64_MAX/1000000ULL)
            vm->max_wall_nanoseconds=(int64_t)parsed*1000000LL;
    }
    const char *max_memory_env=getenv("DIAMOND_MAX_MEMORY_BYTES");
    if(max_memory_env!=nullptr&&max_memory_env[0]!='\0') {
        char *end=nullptr;
        const unsigned long long parsed=strtoull(max_memory_env,&end,10);
        if(end!=max_memory_env&&*end=='\0'&&parsed>0&&parsed<=SIZE_MAX)
            vm->max_memory_bytes=(size_t)parsed;
    }
    vm->resource_limits_active=vm->max_instructions!=0||vm->max_wall_nanoseconds!=0;
    if(vm->max_wall_nanoseconds!=0) {
        struct timespec now;
        clock_gettime(CLOCK_MONOTONIC,&now);
        vm->start_time_ns=(int64_t)now.tv_sec*1000000000LL+(int64_t)now.tv_nsec;
    }
    pthread_once(&mysql_library_init_once,mysql_library_init_once_fn);
    /* A write(2)/SSL_write to a TCP connection the peer has already reset
     * (not just cleanly closed) raises SIGPIPE, whose default disposition
     * is to kill the whole process outright -- surfaced by TLS in
     * particular: OpenSSL servers send a post-handshake NewSessionTicket
     * message automatically for TLS 1.3, and a peer that closes its own
     * socket without ever reading it (the common case for any short-
     * lived connection that errors out or disconnects right after the
     * handshake) leaves that data unread in the kernel receive buffer at
     * close time -- Linux's own trigger for sending RST instead of a
     * plain FIN. Every write-capable I/O path in this file already turns
     * a failed write into a catchable IOError via errno/SSL_get_error,
     * exactly the EPIPE this produces once the fatal signal is out of the
     * way -- so ignoring SIGPIPE here (once per VM, idempotent, matches
     * the universal practice for any long-running networked process) is
     * strictly a bug fix, not a behavior tradeoff: nothing in this VM
     * ever wanted "silently die" as its response to a broken connection. */
    signal(SIGPIPE, SIG_IGN);
    populate_default_argv_env(vm);
}

void diamond_vm_configure_jit_from_env(DiamondVm *vm) {
    /* The native backend has only been validated on glibc x86-64. */
#if (defined(__x86_64__) || defined(_M_X64)) && defined(__GLIBC__)
    vm->jit = getenv("DIAMOND_JIT") != nullptr;
#else
    vm->jit = false;
#endif
    const char *threshold = getenv("DIAMOND_JIT_THRESHOLD");
    if (threshold != nullptr && threshold[0] != '\0') {
        char *end = nullptr;
        const unsigned long long parsed = strtoull(threshold, &end, 10);
        if (end != threshold && *end == '\0' && parsed > 0 &&
            parsed <= SIZE_MAX) {
            vm->jit_threshold = (size_t)parsed;
        }
    }
}

void diamond_vm_bind_fiber_queue(DiamondVm *vm, const DiamondFiberQueue *queue) {
    if(vm==nullptr)return;
    vm->root_queue=queue;
}

static void free_object_list(DiamondObject *object) {
    while (object != nullptr) {
        DiamondObject *next = object->next;
        if(object->kind==DIAMOND_OBJECT_HASH) {
            DiamondHash *hash=(DiamondHash *)object;
            for(size_t index=0;index<hash->constraint_count;index++)
                free(hash->constraints[index].type_variable_bindings);
            free(hash->entries);free(hash->buckets);free(hash->dirty_cards);
        } else if(object->kind==DIAMOND_OBJECT_ARRAY) {
            DiamondArray *array=(DiamondArray *)object;
            for(size_t index=0;index<array->constraint_count;index++)
                free(array->constraints[index].type_variable_bindings);
            free(array->values);free(array->dirty_cards);
        } else if(object->kind==DIAMOND_OBJECT_FIBER) {
            diamond_fiber_free(((DiamondFiberHandle *)object)->fiber);
        } else if(object->kind==DIAMOND_OBJECT_FILE) {
            FILE *stream=((DiamondFileHandle *)object)->stream;
            if(stream!=nullptr)fclose(stream);
        } else if(object->kind==DIAMOND_OBJECT_LISTENER) {
            DiamondListenerHandle *listener=(DiamondListenerHandle *)object;
            if(listener->fd>=0)close(listener->fd);
            if(listener->tls_context!=nullptr)SSL_CTX_free(listener->tls_context);
            free(listener->alpn_protocols);
        } else if(object->kind==DIAMOND_OBJECT_SOCKET) {
            const int fd=((DiamondSocketHandle *)object)->fd;
            if(fd>=0)close(fd);
        } else if(object->kind==DIAMOND_OBJECT_UDP_SOCKET) {
            const int fd=((DiamondUdpSocketHandle *)object)->fd;
            if(fd>=0)close(fd);
        } else if(object->kind==DIAMOND_OBJECT_TLS_SOCKET) {
            DiamondTlsSocketHandle *tls_handle=(DiamondTlsSocketHandle *)object;
            if(tls_handle->ssl!=nullptr) {
                if(!tls_handle->handshake_pending)SSL_shutdown(tls_handle->ssl);
                SSL_free(tls_handle->ssl);
            }
            if(tls_handle->fd>=0)close(tls_handle->fd);
            if(tls_handle->received_session!=nullptr)
                SSL_SESSION_free(tls_handle->received_session);
        } else if(object->kind==DIAMOND_OBJECT_REGEXP) {
            reginold_regex_free(((DiamondRegexp *)object)->handle);
        } else if(object->kind==DIAMOND_OBJECT_PROGRAM_BUILDER) {
            DiamondProgramBuilder *builder=(DiamondProgramBuilder *)object;
            if(builder->source_bundle!=nullptr) {
                diamond_source_bundle_free(builder->source_bundle);
                free(builder->source_bundle);
            }
            diamond_program_free(builder->program);
            free(builder->program);
        } else if(object->kind==DIAMOND_OBJECT_THREAD) {
            free_thread(((DiamondThreadHandle *)object)->thread);
        } else if(object->kind==DIAMOND_OBJECT_CHANNEL) {
            free_channel_reference(((DiamondChannelHandle *)object)->channel);
        } else if(object->kind==DIAMOND_OBJECT_SUPERVISOR) {
            free_supervisor_reference(
                ((DiamondSupervisorHandle *)object)->supervisor);
        } else if(object->kind==DIAMOND_OBJECT_SQLITE3) {
            sqlite3 *db=((DiamondSqlite3Handle *)object)->db;
            /* _v2 -- see the matching branch in diamond_vm_collect_impl
             * above for why. */
            if(db!=nullptr)sqlite3_close_v2(db);
        } else if(object->kind==DIAMOND_OBJECT_SQLITE3_STATEMENT) {
            sqlite3_stmt *stmt=((DiamondSqlite3StatementHandle *)object)->stmt;
            if(stmt!=nullptr)sqlite3_finalize(stmt);
        } else if(object->kind==DIAMOND_OBJECT_POSTGRES) {
            PGconn *conn=((DiamondPostgresHandle *)object)->conn;
            if(conn!=nullptr)PQfinish(conn);
        } else if(object->kind==DIAMOND_OBJECT_MYSQL) {
            MYSQL *conn=((DiamondMysqlHandle *)object)->conn;
            if(conn!=nullptr)mysql_close(conn);
        }
        free(object);
        object = next;
    }
}

void diamond_vm_free(DiamondVm *vm) {
    free_object_list(vm->young_objects);
    free_object_list(vm->old_objects);
    free_adopted_programs(vm->adopted_programs);
    free(vm->class_variables);
    free(vm->gc_protected);
    free(vm->rewritten_sites);
    free(vm->remembered_set);
    *vm = (DiamondVm){};
}

void diamond_vm_invalidate_method_caches(DiamondVm *vm) {
    memset(vm->method_caches,0,sizeof vm->method_caches);
    vm->inline_cache_hits=0;
    vm->inline_cache_misses=0;
    vm->monomorphic_dispatches=0;
    vm->method_cache_probes=0;
}

enum { DIAMOND_FIBER_STACK_SIZE = 8 * 1024 * 1024 };

static bool allocate_fiber_stack(DiamondFiber *fiber) {
    const size_t page = (size_t)sysconf(_SC_PAGESIZE);
    const size_t total = DIAMOND_FIBER_STACK_SIZE + page;
    void *base = mmap(nullptr, total, PROT_READ | PROT_WRITE,
                       MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (base == MAP_FAILED) return false;
    if (mprotect(base, page, PROT_NONE) != 0) {
        munmap(base, total);
        return false;
    }
    fiber->stack = base;
    fiber->stack_size = total;
    return true;
}

static void free_fiber_stack(DiamondFiber *fiber) {
    if (fiber->stack != nullptr) {
        munmap(fiber->stack, fiber->stack_size);
        fiber->stack = nullptr;
        fiber->stack_size = 0;
    }
}

/* thread_local (not a plain file-scope static): this is how diamond_fiber_run
 * smuggles the entering fiber's identity across swapcontext into
 * diamond_fiber_trampoline, which takes no arguments of its own -- one
 * process-wide pointer here would let two OS threads each running their own
 * fibers race writer/reader against each other the moment more than one
 * thread exists (see Thread, docs/threads.md). Each thread gets its own
 * slot, matching how every other piece of per-run state (DiamondVm itself)
 * is already scoped per-thread by construction. */
static thread_local DiamondFiber *diamond_fiber_entering;

static void diamond_fiber_trampoline(void) {
#ifdef DIAMOND_ASAN_FIBERS
    /* First activation of a fresh fiber stack (via makecontext) never
     * "returns" from a swapcontext call the way a resumed one does, so the
     * matching finish lives here instead, with no saved fake stack to
     * restore -- there's no prior history on a stack that's never run. */
    __sanitizer_finish_switch_fiber(nullptr, nullptr, nullptr);
#endif
    DiamondFiber *self = diamond_fiber_entering;
    if (self->entry_closure != nullptr) {
        const DiamondFunction *fn=
            self->program_tables.functions[self->entry_closure->function_index];
        DiamondChunk child={.name=fn->name,.code=fn->code,.lines=fn->lines,
          .columns=fn->columns,.code_count=fn->code_count,.constants=fn->constants,
          .constant_count=fn->constant_count,.strings=fn->strings,.string_count=fn->string_count,
          .type_sets=fn->type_sets,.type_set_count=fn->type_set_count,
          .functions=self->program_tables.functions,.function_count=self->program_tables.function_count,
          .classes=self->program_tables.classes,.class_count=self->program_tables.class_count,
          .interfaces=self->program_tables.interfaces,.interface_count=self->program_tables.interface_count,
          .parameter_type_sets=fn->parameter_type_sets,
          .type_variable_count=fn->type_variable_count,
          .parameter_offset=fn->owner_class==UINT8_MAX?0:1,
          .register_count=fn->register_count};
        self->status=run_chunk(&child,self->vm,nullptr,0,0,self->entry_closure,&self->result);
    } else {
        self->status = run_chunk(self->chunk, self->vm, nullptr, 0, 0, nullptr,
                                 &self->result);
    }
#ifdef DIAMOND_ASAN_FIBERS
    /* This fiber is done for good (completed or failed) and will never be
     * resumed, so its own fake stack should be destroyed rather than saved
     * -- passing nullptr as the first argument is what tells ASan that, per
     * its documented fiber-switch contract -- but the destination we're
     * switching back to still needs real bounds (see
     * diamond_resume_target_bounds). */
    const void *exit_dest_bottom=nullptr;size_t exit_dest_size=0;
    diamond_resume_target_bounds(self,&exit_dest_bottom,&exit_dest_size);
    __sanitizer_start_switch_fiber(nullptr,exit_dest_bottom,exit_dest_size);
#endif
    swapcontext(&self->context, self->resume_target);
}

DiamondFiber *diamond_fiber_new(const DiamondChunk *chunk) {
    DiamondFiber *fiber=calloc(1,sizeof *fiber);
    if(fiber==nullptr)return nullptr;
    fiber->state=DIAMOND_FIBER_NEW;
    fiber->chunk=chunk;
    fiber->result=DIAMOND_NIL;
    fiber->status=DIAMOND_VM_OK;
    return fiber;
}

/* Builds a fiber that invokes a specific closure rather than running a whole
 * chunk from ip=0. Only the sub-tables that are provably stable for the
 * process's lifetime are copied by value -- never chunk->code/constants,
 * which belong to whatever transient stack-local chunk existed at the call
 * site -- so the fiber never retains a pointer that could dangle once that
 * call site returns, however deeply nested Fiber.new(...) was called from. */
static DiamondFiber *diamond_fiber_new_for_closure(
        const DiamondChunk *chunk, const DiamondClosure *closure) {
    DiamondFiber *fiber=diamond_fiber_new(nullptr);
    if(fiber==nullptr)return nullptr;
    fiber->entry_closure=closure;
    fiber->program_tables=(DiamondChunk){
        .functions=chunk->functions,.function_count=chunk->function_count,
        .classes=chunk->classes,.class_count=chunk->class_count,
        .interfaces=chunk->interfaces,.interface_count=chunk->interface_count,
    };
    return fiber;
}

void diamond_fiber_free(DiamondFiber *fiber) {
    if(fiber==nullptr)return;
    free_fiber_stack(fiber);
    free(fiber);
}

DiamondFiberStatus diamond_fiber_prepare(DiamondFiber *fiber) {
    if(fiber==nullptr||fiber->state!=DIAMOND_FIBER_NEW||
       (fiber->chunk==nullptr&&fiber->entry_closure==nullptr))
        return DIAMOND_FIBER_INVALID_STATE;
    if(!allocate_fiber_stack(fiber))return DIAMOND_FIBER_INVALID_STATE;
    if(getcontext(&fiber->context)!=0) {
        free_fiber_stack(fiber);
        return DIAMOND_FIBER_INVALID_STATE;
    }
    const size_t page=(size_t)sysconf(_SC_PAGESIZE);
    fiber->context.uc_stack.ss_sp=(char *)fiber->stack+page;
    fiber->context.uc_stack.ss_size=DIAMOND_FIBER_STACK_SIZE;
    fiber->context.uc_link=nullptr;
    makecontext(&fiber->context,diamond_fiber_trampoline,0);
    fiber->state=DIAMOND_FIBER_RUNNABLE;return DIAMOND_FIBER_OK;
}

DiamondFiberStatus diamond_fiber_bind_vm(DiamondFiber *fiber, DiamondVm *vm) {
    if(fiber==nullptr||vm==nullptr||fiber->state==DIAMOND_FIBER_COMPLETED||
       fiber->state==DIAMOND_FIBER_FAILED)return DIAMOND_FIBER_INVALID_STATE;
    fiber->vm=vm;return DIAMOND_FIBER_OK;
}

DiamondFiberStatus diamond_fiber_run(DiamondFiber *fiber) {
    if(fiber==nullptr||fiber->state!=DIAMOND_FIBER_RUNNING||fiber->vm==nullptr||
       (fiber->chunk==nullptr&&fiber->entry_closure==nullptr))
        return DIAMOND_FIBER_INVALID_STATE;
    DiamondVm *vm=fiber->vm;
    void *saved_frames=vm->frames;
    DiamondFiber *saved_running=vm->running_fiber;
    fiber->resumer_frames=saved_frames;
    fiber->resumer_fiber=saved_running;
    vm->frames=fiber->native_frames;
    vm->running_fiber=fiber;
    diamond_fiber_entering=fiber;
    ucontext_t caller_context;
    fiber->resume_target=&caller_context;
#ifdef DIAMOND_ASAN_FIBERS
    /* Entering the fiber's own stack (fresh via makecontext, or resuming one
     * parked at a prior yield) -- its bounds are always exactly known since
     * this VM owns the mmap. caller_fake_stack is a plain local: it's
     * produced right before this swapcontext and consumed right after it
     * returns, both in this same call, since re-entering this fiber always
     * comes back through here. */
    void *caller_fake_stack=nullptr;
    __sanitizer_start_switch_fiber(&caller_fake_stack,
        fiber->context.uc_stack.ss_sp,fiber->context.uc_stack.ss_size);
#endif
    swapcontext(&caller_context,&fiber->context);
#ifdef DIAMOND_ASAN_FIBERS
    __sanitizer_finish_switch_fiber(caller_fake_stack,nullptr,nullptr);
#endif
    fiber->native_frames=vm->frames;
    vm->frames=saved_frames;
    vm->running_fiber=saved_running;
    fiber->resumer_frames=nullptr;
    fiber->resumer_fiber=nullptr;
    fiber->state=fiber->status==DIAMOND_VM_OK?DIAMOND_FIBER_COMPLETED:
        (fiber->status==DIAMOND_VM_YIELDED?DIAMOND_FIBER_SUSPENDED:
         DIAMOND_FIBER_FAILED);
    return DIAMOND_FIBER_OK;
}

DiamondValue diamond_fiber_result(const DiamondFiber *fiber) {
    return fiber == nullptr ? DIAMOND_NIL : fiber->result;
}

DiamondVmStatus diamond_fiber_status(const DiamondFiber *fiber) {
    return fiber == nullptr ? DIAMOND_VM_INVALID_BYTECODE : fiber->status;
}

bool diamond_fiber_resumable(const DiamondFiber *fiber) {
    return fiber!=nullptr && (fiber->state==DIAMOND_FIBER_RUNNABLE||
        fiber->state==DIAMOND_FIBER_SUSPENDED);
}

const char *diamond_fiber_state_name(DiamondFiberState state) {
    switch(state) {
        case DIAMOND_FIBER_NEW:return "new";
        case DIAMOND_FIBER_RUNNABLE:return "runnable";
        case DIAMOND_FIBER_RUNNING:return "running";
        case DIAMOND_FIBER_SUSPENDED:return "suspended";
        case DIAMOND_FIBER_COMPLETED:return "completed";
        case DIAMOND_FIBER_FAILED:return "failed";
    }
    return "unknown";
}

DiamondFiberStatus diamond_fiber_make_runnable(DiamondFiber *fiber) {
    if(fiber==nullptr||(fiber->state!=DIAMOND_FIBER_NEW&&
       fiber->state!=DIAMOND_FIBER_SUSPENDED))return DIAMOND_FIBER_INVALID_STATE;
    fiber->state=DIAMOND_FIBER_RUNNABLE;return DIAMOND_FIBER_OK;
}

DiamondFiberStatus diamond_fiber_begin(DiamondFiber *fiber) {
    if(fiber==nullptr||fiber->state!=DIAMOND_FIBER_RUNNABLE)
        return DIAMOND_FIBER_INVALID_STATE;
    fiber->state=DIAMOND_FIBER_RUNNING;return DIAMOND_FIBER_OK;
}

DiamondFiberStatus diamond_fiber_resume(DiamondFiber *fiber, DiamondValue value) {
    if(fiber==nullptr||(fiber->state!=DIAMOND_FIBER_RUNNABLE&&
       fiber->state!=DIAMOND_FIBER_SUSPENDED))return DIAMOND_FIBER_INVALID_STATE;
    fiber->resume_value=value;
    fiber->state=DIAMOND_FIBER_RUNNING;return DIAMOND_FIBER_OK;
}

DiamondFiberStatus diamond_fiber_suspend(DiamondFiber *fiber) {
    if(fiber==nullptr||fiber->state!=DIAMOND_FIBER_RUNNING)
        return DIAMOND_FIBER_INVALID_STATE;
    fiber->state=DIAMOND_FIBER_SUSPENDED;return DIAMOND_FIBER_OK;
}

DiamondFiberStatus diamond_fiber_yield(DiamondFiber *fiber) {
    return diamond_fiber_suspend(fiber);
}

DiamondFiberStatus diamond_fiber_complete(DiamondFiber *fiber, DiamondValue result) {
    if(fiber==nullptr||fiber->state!=DIAMOND_FIBER_RUNNING)
        return DIAMOND_FIBER_INVALID_STATE;
    fiber->result=result;fiber->status=DIAMOND_VM_OK;
    fiber->state=DIAMOND_FIBER_COMPLETED;return DIAMOND_FIBER_OK;
}

DiamondFiberStatus diamond_fiber_fail(DiamondFiber *fiber, DiamondVmStatus status) {
    if(fiber==nullptr||fiber->state!=DIAMOND_FIBER_RUNNING)
        return DIAMOND_FIBER_INVALID_STATE;
    fiber->status=status;fiber->state=DIAMOND_FIBER_FAILED;
    return DIAMOND_FIBER_OK;
}

void diamond_fiber_queue_init(DiamondFiberQueue *queue) {
    *queue=(DiamondFiberQueue){};
}

void diamond_fiber_queue_free(DiamondFiberQueue *queue) {
    free(queue->items);*queue=(DiamondFiberQueue){};
}

bool diamond_fiber_queue_push(DiamondFiberQueue *queue, DiamondFiber *fiber) {
    if(fiber==nullptr||fiber->state!=DIAMOND_FIBER_RUNNABLE)return false;
    if(queue->head>0&&queue->count==queue->capacity) {
        const size_t pending=queue->count-queue->head;
        memmove(queue->items,queue->items+queue->head,pending*sizeof *queue->items);
        queue->head=0;queue->count=pending;
    }
    if(queue->count==queue->capacity) {
        const size_t capacity=queue->capacity==0?8:queue->capacity*2;
        DiamondFiber **items=realloc(queue->items,capacity*sizeof *items);
        if(items==nullptr)return false;
        queue->items=items;queue->capacity=capacity;
    }
    queue->items[queue->count++]=fiber;return true;
}

DiamondFiber *diamond_fiber_queue_pop(DiamondFiberQueue *queue) {
    if(queue->head==queue->count)return nullptr;
    DiamondFiber *fiber=queue->items[queue->head++];
    if(queue->head==queue->count)queue->head=queue->count=0;
    if(fiber->state==DIAMOND_FIBER_RUNNABLE)fiber->state=DIAMOND_FIBER_RUNNING;
    return fiber;
}

size_t diamond_fiber_queue_count(const DiamondFiberQueue *queue) {
    return queue==nullptr?0:queue->count-queue->head;
}

DiamondFiber *diamond_fiber_queue_at(const DiamondFiberQueue *queue, size_t index) {
    if(queue==nullptr||index>=diamond_fiber_queue_count(queue))return nullptr;
    return queue->items[queue->head+index];
}

DiamondFiber *diamond_fiber_scheduler_step(DiamondFiberQueue *queue) {
    return diamond_fiber_queue_pop(queue);
}

bool diamond_fiber_scheduler_requeue(DiamondFiberQueue *queue, DiamondFiber *fiber) {
    if(fiber==nullptr||fiber->state!=DIAMOND_FIBER_SUSPENDED)return false;
    fiber->state=DIAMOND_FIBER_RUNNABLE;
    if(!diamond_fiber_queue_push(queue,fiber)) {
        fiber->state=DIAMOND_FIBER_SUSPENDED;return false;
    }
    return true;
}

DiamondFiberStatus diamond_fiber_scheduler_run_once(DiamondFiberQueue *queue) {
    DiamondFiber *fiber=diamond_fiber_scheduler_step(queue);
    if(fiber==nullptr)return DIAMOND_FIBER_INVALID_STATE;
    if(diamond_fiber_run(fiber)!=DIAMOND_FIBER_OK)return DIAMOND_FIBER_INVALID_STATE;
    if(fiber->state==DIAMOND_FIBER_SUSPENDED&&
       !diamond_fiber_scheduler_requeue(queue,fiber))return DIAMOND_FIBER_INVALID_STATE;
    return DIAMOND_FIBER_OK;
}

DiamondFiberStatus diamond_fiber_scheduler_run_all(DiamondFiberQueue *queue) {
    if(queue==nullptr)return DIAMOND_FIBER_INVALID_STATE;
    while(diamond_fiber_queue_count(queue)>0) {
        if(diamond_fiber_scheduler_run_once(queue)!=DIAMOND_FIBER_OK)
            return DIAMOND_FIBER_INVALID_STATE;
    }
    return DIAMOND_FIBER_OK;
}

DiamondString *allocate_string(DiamondVm *vm, const char *chars,
                                      size_t length) {
    if (!maybe_collect(vm)) return nullptr;
    DiamondString *string = malloc(sizeof(DiamondString) + length + 1);
    if (string == nullptr) return nullptr;
    string->object = (DiamondObject){
        .next = vm->young_objects,
        .kind = DIAMOND_OBJECT_STRING,
    };
    string->length = length;
    /* `chars` can be nullptr here with length 0 -- an empty StringBuilder
     * (File#read at EOF, an empty gets() line, ...) never allocates its
     * `chars` buffer at all. memcpy's first two arguments are declared
     * never-null regardless of the length passed, so calling it with a
     * null source is undefined behavior even when it would copy zero
     * bytes (confirmed live under UBSan: "null pointer passed as
     * argument 2, which is declared to never be null"). */
    if (length > 0) memcpy(string->chars, chars, length);
    string->chars[length] = '\0';
    vm->young_objects = &string->object;
    vm->bytes_allocated += sizeof(DiamondString) + length + 1;
    return string;
}

/* JIT trampoline for DIAMOND_OP_STRING -- see jit.h's own comment. Mirrors
 * that opcode's own interpreter case exactly (src/vm.c's dispatch loop):
 * resolve the string constant, allocate via allocate_string (which calls
 * maybe_collect unconditionally -- the actual reason this whole trampoline
 * needs the caller to have already published a DiamondFrame, unlike
 * SET_IVAR/INDEX_GET/CHECK_TYPE). */
DiamondVmStatus diamond_jit_new_string(DiamondVm *vm, const DiamondChunk *chunk,
        uint16_t string_index, DiamondValue *out) {
    if (string_index >= chunk->string_count) return DIAMOND_VM_INVALID_BYTECODE;
    const DiamondStringConstant *constant = &chunk->strings[string_index];
    DiamondString *string = allocate_string(vm, constant->chars, constant->length);
    if (string == nullptr) return DIAMOND_VM_OUT_OF_MEMORY;
    *out = DIAMOND_OBJECT(string);
    return DIAMOND_VM_OK;
}

static DiamondSymbol *allocate_symbol(DiamondVm *vm, const char *chars,
                                      size_t length) {
    if (!maybe_collect(vm)) return nullptr;
    DiamondSymbol *symbol = malloc(sizeof(DiamondSymbol) + length + 1);
    if (symbol == nullptr) return nullptr;
    symbol->object = (DiamondObject){
        .next = vm->young_objects,
        .kind = DIAMOND_OBJECT_SYMBOL,
    };
    symbol->length = length;
    /* See allocate_string's own comment just above: a null `chars` with
     * length 0 is well-defined for every current caller (a String/Symbol
     * object's own `chars` is never null, even empty), but the same
     * memcpy-is-UB-on-null rule applies here too, so guard it identically
     * rather than relying on that staying true. */
    if (length > 0) memcpy(symbol->chars, chars, length);
    symbol->chars[length] = '\0';
    vm->young_objects = &symbol->object;
    vm->bytes_allocated += sizeof(DiamondSymbol) + length + 1;
    return symbol;
}

static DiamondInstance *allocate_instance(DiamondVm *vm,const DiamondClass *class,
                                          const DiamondChunk *chunk) {
    if (!maybe_collect(vm)) return nullptr;
    const size_t size=sizeof(DiamondInstance)+class->field_count*sizeof(DiamondValue);
    DiamondInstance *instance=malloc(size); if(instance==nullptr)return nullptr;
    instance->object=(DiamondObject){.next=vm->young_objects,.kind=DIAMOND_OBJECT_INSTANCE};
    instance->class=class; instance->shape=&class->shapes[0]; instance->owner=chunk;
    instance->field_count=class->field_count;
    for(size_t i=0;i<instance->field_count;i++) instance->fields[i]=DIAMOND_NIL;
    vm->young_objects=&instance->object; vm->bytes_allocated+=size; return instance;
}

/* Same allocation as allocate_array below, minus populating `values` --
 * for a caller that already has (or is about to build) exactly `count`
 * DiamondValues and would otherwise have to stage them in a throwaway
 * buffer first just to hand them to allocate_array for a second copy
 * (add_fallback's Array+Array, below, used to do exactly that). Safe to
 * defer reading any *other* array's contents until after this returns,
 * the same way allocate_array's own copy loop already runs after its
 * maybe_collect: DiamondArray objects are never moved by GC, so a source
 * still reachable from a live register (this VM has no other kind of
 * temporary) stays exactly where it was regardless of what maybe_collect
 * did meanwhile. */
static DiamondArray *allocate_array_uninitialized(DiamondVm *vm,size_t count) {
    if (!maybe_collect(vm)) return nullptr;
    const size_t capacity=count;
    const size_t size=sizeof(DiamondArray)+capacity*sizeof(DiamondValue);
    DiamondArray *array=malloc(sizeof(DiamondArray)); if(array==nullptr)return nullptr;
    array->values=capacity==0?nullptr:malloc(capacity*sizeof(DiamondValue));
    if(capacity>0&&array->values==nullptr){free(array);return nullptr;}
    array->object=(DiamondObject){.next=vm->young_objects,.kind=DIAMOND_OBJECT_ARRAY};
    array->count=count;array->capacity=capacity;array->constraint_count=0;
    array->dirty_cards=nullptr;array->dirty_card_capacity=0;
    vm->young_objects=&array->object;vm->bytes_allocated+=size;return array;
}

DiamondArray *allocate_array(DiamondVm *vm,const DiamondValue *values,
                                    size_t count) {
    DiamondArray *array=allocate_array_uninitialized(vm,count);
    if(array==nullptr)return nullptr;
    if(count>0)memcpy(array->values,values,count*sizeof *values);
    return array;
}

DiamondHash *allocate_hash(DiamondVm *vm) {
    if (!maybe_collect(vm)) return nullptr;
    DiamondHash *hash=malloc(sizeof(DiamondHash)); if(hash==nullptr)return nullptr;
    *hash=(DiamondHash){.object={.next=vm->young_objects,.kind=DIAMOND_OBJECT_HASH}};
    vm->young_objects=&hash->object;vm->bytes_allocated+=sizeof(DiamondHash);return hash;
}

/* diamond_vm_init's own default for argv_value/env_value -- see that
 * field's comment in vm.h. Best-effort: an allocation failure partway
 * through (env_value in particular, since a real environment can have
 * dozens of entries) just stops early rather than failing VM
 * construction outright -- diamond_vm_init has no error return, and an
 * incomplete ENV is a far better failure mode than none at all when
 * memory is already this tight. */
static void populate_default_argv_env(DiamondVm *vm) {
    DiamondArray *argv=allocate_array(vm,nullptr,0);
    if(argv!=nullptr)vm->argv_value=DIAMOND_OBJECT(argv);
    DiamondHash *env=allocate_hash(vm);
    if(env==nullptr)return;
    vm->env_value=DIAMOND_OBJECT(env);
    for(char **entry=environ;entry!=nullptr&&*entry!=nullptr;entry++) {
        const char *equals=strchr(*entry,'=');
        if(equals==nullptr)continue;
        const size_t key_length=(size_t)(equals-*entry);
        DiamondString *key=allocate_string(vm,*entry,key_length);
        if(key==nullptr)return;
        /* key isn't stored into env (the only thing that would make it
         * GC-visible) until hash_set below -- the allocate_string call for
         * value, right here, can itself trigger a collection (same
         * bytes_allocated>=next_gc check every allocate_* helper makes),
         * which would free key out from under hash_set's own hash_value(key)
         * call. Confirmed via ASan as a real heap-use-after-free, not just
         * theoretical -- same "root the container first, populate
         * incrementally" lesson as regexp_scan_helper/copy_value_into_vm
         * (see docs/roadmap.md), just not yet applied to this newer site. */
        const size_t key_mark=vm->gc_protected_count;
        if(!gc_protect(vm,DIAMOND_OBJECT(key)))return;
        DiamondString *value=allocate_string(vm,equals+1,strlen(equals+1));
        if(value==nullptr){gc_unprotect(vm,key_mark);return;}
        const bool inserted=hash_set(vm,env,DIAMOND_OBJECT(key),DIAMOND_OBJECT(value));
        gc_unprotect(vm,key_mark);
        if(!inserted)return;
    }
}

/* Replaces the default empty ARGV (see populate_default_argv_env above)
 * with the real trailing command-line arguments a top-level script was
 * actually invoked with -- called once, by src/run_source.c, after
 * diamond_vm_init. Not used by a spawned Thread's child_vm or
 * ProgramBuilder#run's internal VM, which keep the empty default (see
 * argv_value's own comment in vm.h for why). Best-effort like
 * populate_default_argv_env: an allocation failure here just leaves
 * ARGV at whatever it already had (the empty default, or a partial
 * prefix), rather than a hard failure with no sensible status to report
 * through this void-returning function. */
void diamond_vm_set_argv(DiamondVm *vm, int argc, char *const *argv) {
    if(argc<=0||argv==nullptr)return;
    DiamondArray *array=allocate_array(vm,nullptr,0);
    if(array==nullptr)return;
    vm->argv_value=DIAMOND_OBJECT(array);
    for(int index=0;index<argc;index++) {
        DiamondString *piece=allocate_string(vm,argv[index],strlen(argv[index]));
        if(piece==nullptr)return;
        if(!array_push(vm,array,DIAMOND_OBJECT(piece)))return;
    }
}

static DiamondClosure *allocate_closure(DiamondVm *vm,uint16_t function_index,
                                        const DiamondValue *captures,size_t count) {
    if (!maybe_collect(vm)) return nullptr;
    DiamondClosure *closure=malloc(sizeof(DiamondClosure));if(closure==nullptr)return nullptr;
    *closure=(DiamondClosure){.object={.next=vm->young_objects,.kind=DIAMOND_OBJECT_CLOSURE},
      .function_index=function_index,.capture_count=(uint8_t)count};
    for(size_t i=0;i<count;i++)closure->captures[i]=captures[i];
    vm->young_objects=&closure->object;vm->bytes_allocated+=sizeof(DiamondClosure);return closure;
}

static DiamondCell *allocate_cell(DiamondVm *vm,DiamondValue value) {
    if (!maybe_collect(vm)) return nullptr;
    DiamondCell *cell=malloc(sizeof(DiamondCell));if(cell==nullptr)return nullptr;
    *cell=(DiamondCell){.object={.next=vm->young_objects,.kind=DIAMOND_OBJECT_CELL},.value=value};
    vm->young_objects=&cell->object;vm->bytes_allocated+=sizeof(DiamondCell);return cell;
}

static DiamondFiberHandle *allocate_fiber_handle(DiamondVm *vm,DiamondFiber *fiber) {
    if (!maybe_collect(vm)) return nullptr;
    DiamondFiberHandle *handle=malloc(sizeof(DiamondFiberHandle));if(handle==nullptr)return nullptr;
    *handle=(DiamondFiberHandle){.object={.next=vm->young_objects,.kind=DIAMOND_OBJECT_FIBER},.fiber=fiber};
    vm->young_objects=&handle->object;vm->bytes_allocated+=sizeof(DiamondFiberHandle);return handle;
}

/* A raw OS-thread limit, not a language-level tuning knob: real pthreads
 * are a genuinely limited, comparatively expensive OS resource (unlike
 * Fibers, cheap userspace stacks) and each one commits a cloned program --
 * 64 bounds resource use while still comfortably
 * covering the "a handful of coarse-grained parallel workers" use case
 * this primitive targets, and turns a runaway recursive Thread.new bug
 * into a prompt ThreadError instead of exhausting the host. Process-wide
 * (not per-DiamondVm) since threads spawned from unrelated VMs still
 * compete for the same real OS/memory resources. */
enum { DIAMOND_MAX_THREADS = 64 };
static atomic_size_t diamond_active_thread_count = 0;

/* OS threads currently running Diamond code: Thread.new workers and
 * supervised children, counted from just before pthread_create until their
 * entry function returns. Unlike diamond_active_thread_count, a finished
 * but not yet reaped thread doesn't count. See diamond_vm_running_threads. */
static atomic_size_t diamond_running_thread_count = 0;

size_t diamond_vm_running_threads(void) {
    return atomic_load(&diamond_running_thread_count);
}

/* Off unless the process owner turns it on: an embedder running many
 * programs in one process (tests/run_cases.c) must not be exited by one of
 * them. */
static atomic_bool diamond_exit_on_threaded_failure = false;

void diamond_vm_set_exit_on_threaded_failure(bool enabled) {
    atomic_store(&diamond_exit_on_threaded_failure,enabled);
}

void diamond_vm_exit_if_threads_running(int status) {
    if(!atomic_load(&diamond_exit_on_threaded_failure))return;
    if(atomic_load(&diamond_running_thread_count)==0)return;
    fflush(stdout);
    fflush(stderr);
    exit(status);
}

/* run_chunk's deliberately fixed-size interpreter frame is large (see the
 * native-recursion-limit comment near the top of this file), so libc's
 * pthread default is part of the VM's effective call-depth contract unless
 * Diamond overrides it. glibc happens to inherit an 8 MiB default, while
 * musl commonly supplies only about 128 KiB and Darwin 512 KiB: ordinary
 * Thread.new code can exhaust the former, and the language-level recursion
 * guard cannot fire before the latter's native stack is already gone.
 *
 * Keep language threads aligned with Diamond fibers and the stack size used
 * to calibrate DIAMOND_MAX_CALL_DEPTH. Small native worker threads such as
 * Tensor#matmul do not run the interpreter and intentionally keep their
 * platform defaults. */
enum { DIAMOND_VM_THREAD_STACK_SIZE = 8 * 1024 * 1024 };

static int create_vm_thread(pthread_t *handle,
        void *(*entry)(void *), void *argument) {
    pthread_attr_t attributes;
    int status=pthread_attr_init(&attributes);
    if(status!=0)return status;
    status=pthread_attr_setstacksize(&attributes,DIAMOND_VM_THREAD_STACK_SIZE);
    if(status==0) {
        /* Counted before the thread can possibly finish, and uncounted by
         * the entry function itself on its way out. */
        atomic_fetch_add(&diamond_running_thread_count,1);
        status=pthread_create(handle,&attributes,entry,argument);
        if(status!=0)atomic_fetch_sub(&diamond_running_thread_count,1);
    }
    pthread_attr_destroy(&attributes);
    return status;
}

/* Builds a fresh, independently-owned DiamondProgram whose
 * function records and classes[]/interfaces[] tables are a deep copy of
 * whatever program `chunk` is a view into -- see docs/threads.md. Used by
 * Thread.new so the spawned thread runs against its own program, never
 * the ambient one (sidesteps REDEFINE_METHOD racing another thread's own
 * dispatch entirely, rather than trying to synchronize it).
 * diamond_program_init handles every field DiamondChunk doesn't expose
 * (modules[]/namespace_constants[]/entry/entry_path) -- all purely
 * compile-time bookkeeping never read by run_chunk (confirmed by their
 * total absence from DiamondChunk itself), so leaving them at
 * diamond_program_init's own defaults is correct, not a gap. The three
 * fixed class/interface arrays are copied directly; independently allocated
 * function records keep thread-local method replacement isolated. Returns
 * nullptr only on allocation failure. */
static DiamondProgram *clone_program_from_chunk(const DiamondChunk *chunk) {
    DiamondProgram *clone=calloc(1,sizeof *clone);
    if(clone==nullptr)return nullptr;
    /* _fresh, not diamond_program_init: `clone` is freshly calloc'd right
     * above (already all-zero) and never reused across calls -- a new
     * Thread.new spawn always gets its own brand-new clone -- so
     * diamond_program_init's own memset would just re-zero memory
     * calloc already zeroed. See its own comment (src/compiler.c). */
    diamond_program_init_fresh(clone);
    if(chunk->type_set_count>0) {
        if(!diamond_function_reserve_type_sets(&clone->entry,
                chunk->type_set_count)) {
            diamond_program_free(clone);free(clone);return nullptr;
        }
        memcpy(clone->entry.type_sets,chunk->type_sets,
            chunk->type_set_count*sizeof *clone->entry.type_sets);
        clone->entry.type_set_count=chunk->type_set_count;
    }
    for(size_t index=0;index<chunk->function_count;index++) {
        DiamondFunction *function=diamond_program_add_function(clone);
        if(function==nullptr) {
            diamond_program_free(clone);free(clone);return nullptr;
        }
        if(!diamond_function_copy(function,chunk->functions[index])) {
            diamond_program_free(clone);free(clone);return nullptr;
        }
    }
    memcpy(clone->classes,chunk->classes,sizeof clone->classes);
    clone->class_count=chunk->class_count;
    memcpy(clone->interfaces,chunk->interfaces,sizeof clone->interfaces);
    clone->interface_count=chunk->interface_count;
    for(size_t index=0;index<clone->interface_count;index++)
        clone->interfaces[index].type_sets=clone->entry.type_sets;
    clone->range_class_index=chunk->range_class_index;
    return clone;
}

/* pthread_create's entry point for a spawned Thread -- runs entirely
 * against `thread`'s own child_vm/child_program (see docs/threads.md),
 * never touching anything owned by the spawning thread, so this needs no
 * reference back into whatever chunk was ambient at Thread.new time (the
 * function to run is looked up in the *clone's* own functions[] table, by
 * the same function_index DIAMOND_OP_THREAD_NEW captured from the
 * closure). Populates the same finished/result/raised/internal_failure
 * contract DIAMOND_OP_THREAD_NEW's own synchronous stub previously did
 * inline -- .join() (run_chunk's INVOKE case) doesn't know or care
 * whether that contract was filled in synchronously or by a real OS
 * thread. Sets `finished` last and unconditionally, exactly once, since
 * that's the only field .alive?() reads without holding join_lock. */
static void *thread_entry_trampoline(void *argument) {
    DiamondThread *thread=(DiamondThread *)argument;
    const DiamondFunction *target_fn=
        thread->child_program->functions[thread->function_index];
    const DiamondChunk child_chunk={
        .name=target_fn->name,.code=target_fn->code,
        .lines=target_fn->lines,.columns=target_fn->columns,
        .code_count=target_fn->code_count,
        .constants=target_fn->constants,.constant_count=target_fn->constant_count,
        .strings=target_fn->strings,.string_count=target_fn->string_count,
        .type_sets=target_fn->type_sets,.type_set_count=target_fn->type_set_count,
        .functions=thread->child_program->functions,
        .function_count=thread->child_program->function_count,
        .classes=thread->child_program->classes,
        .class_count=thread->child_program->class_count,
        .interfaces=thread->child_program->interfaces,
        .interface_count=thread->child_program->interface_count,
        .parameter_type_sets=target_fn->parameter_type_sets,
        .type_variable_count=target_fn->type_variable_count,
        .parameter_offset=target_fn->owner_class==UINT8_MAX?0:1,
        .register_count=target_fn->register_count,
        .has_variadic=target_fn->has_variadic,
        .range_class_index=thread->child_program->range_class_index};
    /* This trampoline calls run_chunk directly rather than through
     * diamond_vm_run (this is a spawned Thread's own dedicated entry
     * point, on its own OS thread, never diamond_vm_run's top-level
     * caller), so it has to seed range_class_index onto child_vm itself
     * here -- diamond_vm_run's own copy of this same assignment never
     * runs for a Thread. See DiamondVm's own comment on this field.
     * root_chunk needs the same seeding, for the same reason -- &child_chunk
     * is safe to store there despite being a local: root_chunk is only
     * ever read while run_chunk(&child_chunk,...) below is still on the
     * stack, the same lifetime child_chunk itself already relies on. */
    thread->child_vm->range_class_index=thread->child_program->range_class_index;
    thread->child_vm->root_chunk=&child_chunk;
    DiamondValue run_result=DIAMOND_NIL;
    const DiamondVmStatus run_status=run_chunk(&child_chunk,thread->child_vm,
        thread->args,thread->arg_count,0,nullptr,&run_result);
    if(run_status==DIAMOND_VM_EXCEPTION) {
        thread->result=thread->child_vm->exception;thread->raised=true;
    } else if(run_status!=DIAMOND_VM_OK) {
        thread->internal_failure=true;
    } else {
        thread->result=run_result;
    }
    atomic_store(&thread->finished,true);
    atomic_fetch_sub(&diamond_running_thread_count,1);
    return nullptr;
}

static DiamondThreadHandle *allocate_thread_handle(DiamondVm *vm,DiamondThread *thread) {
    if (!maybe_collect(vm)) return nullptr;
    DiamondThreadHandle *handle=malloc(sizeof(DiamondThreadHandle));if(handle==nullptr)return nullptr;
    *handle=(DiamondThreadHandle){.object={.next=vm->young_objects,.kind=DIAMOND_OBJECT_THREAD},.thread=thread};
    vm->young_objects=&handle->object;vm->bytes_allocated+=sizeof(DiamondThreadHandle);return handle;
}

/* Shared teardown for a DiamondThread, called from both diamond_vm_collect's
 * cycle-based sweep and diamond_vm_free's whole-VM teardown loop (mirroring
 * diamond_fiber_free's own role for DIAMOND_OBJECT_FIBER) -- guarantees no
 * real OS thread ever outlives its DiamondThreadHandle's GC lifetime: if a
 * spawned-but-never-.join()'d thread's handle becomes unreachable (or the
 * whole VM is shutting down), this blocks on pthread_join right here before
 * reclaiming the thread's own fully independent child_vm/child_program.
 * `thread` itself may be nullptr (mirrors diamond_fiber_free's own
 * nullptr-tolerance) so callers don't need their own guard. The sole
 * decrement matching DIAMOND_OP_THREAD_NEW's own increment of
 * diamond_active_thread_count also lives here -- this is the one place
 * every DiamondThread's lifecycle is guaranteed to pass through exactly
 * once, whether reaped after a normal .join() or cleaned up from a
 * spawn-time failure partway through construction. */
static void free_thread(DiamondThread *thread) {
    if(thread==nullptr)return;
    if(thread->spawned&&!thread->joined) {
        pthread_join(thread->handle,nullptr);
        thread->joined=true;
    }
    if(thread->child_vm!=nullptr) {
        diamond_vm_free(thread->child_vm);
        free(thread->child_vm);
    }
    diamond_program_free(thread->child_program);
    free(thread->child_program);
    pthread_mutex_destroy(&thread->join_lock);
    free(thread);
    atomic_fetch_sub(&diamond_active_thread_count,1);
}

static DiamondChannelHandle *allocate_channel_handle(DiamondVm *vm,DiamondChannel *channel) {
    if (!maybe_collect(vm)) return nullptr;
    DiamondChannelHandle *handle=malloc(sizeof(DiamondChannelHandle));
    if(handle==nullptr)return nullptr;
    *handle=(DiamondChannelHandle){.object={.next=vm->young_objects,.kind=DIAMOND_OBJECT_CHANNEL},
        .channel=channel};
    vm->young_objects=&handle->object;vm->bytes_allocated+=sizeof(DiamondChannelHandle);
    return handle;
}

/* Mirrors free_thread's own role, called from the same two sweep paths
 * (diamond_vm_collect's cycle-based sweep, diamond_vm_free's whole-VM
 * teardown) for a DIAMOND_OBJECT_CHANNEL handle -- except a DiamondChannel
 * is refcounted (see its own comment) rather than owned one-to-one by a
 * single handle, so this only actually tears anything down once the
 * *last* referencing handle, across however many VM heaps ever held one,
 * is swept. Safe by construction at that point: reachability is exactly
 * what the GC just proved false for every one of those handles, so no
 * thread can be mid-call (send/receive/close/...) against a channel whose
 * last reference is about to disappear. `channel` may be nullptr (mirrors
 * free_thread's own tolerance) so callers don't need their own guard. */
static void free_channel_reference(DiamondChannel *channel) {
    if(channel==nullptr)return;
    if(atomic_fetch_sub(&channel->refcount,1)!=1)return;
    pthread_mutex_destroy(&channel->lock);
    pthread_cond_destroy(&channel->not_empty);
    pthread_cond_destroy(&channel->not_full);
    if(channel->private_vm!=nullptr) {
        diamond_vm_free(channel->private_vm);
        free(channel->private_vm);
    }
    diamond_program_free(channel->private_program);
    free(channel->private_program);
    free(channel->queue);
    free(channel);
}

/* pthread_create's entry point for one supervised child -- unlike
 * thread_entry_trampoline (a single run, one OS thread per Thread.new
 * call), this loops for the child's *entire* supervised lifetime: a
 * fresh DiamondVm/heap per attempt, freed at the end of every attempt
 * whether it crashed or not, exactly the isolated-heap-per-run guarantee
 * an ordinary Thread already gives a single spawn. A clean, non-raising
 * return ends the loop for good (v1 restarts on crash only, never on a
 * normal return -- see docs/threads.md); an uncaught exception or
 * internal VM failure records the reason, bumps restart_count, and
 * loops again after a fixed 20ms delay (a safety valve bounding CPU use
 * from a child that crashes immediately every time, not a configurable
 * backoff policy -- see docs/roadmap.md's "what's next" note) unless
 * stop_requested has been set meanwhile. Builds its own synthetic
 * DiamondChunk once, up front, exactly the shape thread_entry_
 * trampoline's own local `child_chunk` already uses -- program_template
 * never changes across restarts, so this doesn't need rebuilding per
 * iteration the way thread_entry_trampoline's per-spawn one does. */
static void *supervisor_child_entry_trampoline(void *argument) {
    DiamondSupervisorChild *child=(DiamondSupervisorChild *)argument;
    DiamondSupervisor *supervisor=child->supervisor;
    const DiamondFunction *target_fn=
        child->program_template->functions[child->function_index];
    const DiamondChunk child_chunk={
        .name=target_fn->name,.code=target_fn->code,
        .lines=target_fn->lines,.columns=target_fn->columns,
        .code_count=target_fn->code_count,
        .constants=target_fn->constants,.constant_count=target_fn->constant_count,
        .strings=target_fn->strings,.string_count=target_fn->string_count,
        .type_sets=target_fn->type_sets,.type_set_count=target_fn->type_set_count,
        .functions=child->program_template->functions,
        .function_count=child->program_template->function_count,
        .classes=child->program_template->classes,
        .class_count=child->program_template->class_count,
        .interfaces=child->program_template->interfaces,
        .interface_count=child->program_template->interface_count,
        .parameter_type_sets=target_fn->parameter_type_sets,
        .type_variable_count=target_fn->type_variable_count,
        .parameter_offset=target_fn->owner_class==UINT8_MAX?0:1,
        .register_count=target_fn->register_count,
        .has_variadic=target_fn->has_variadic,
        .range_class_index=child->program_template->range_class_index};
    for(;;) {
        DiamondVm *run_vm=malloc(sizeof *run_vm);
        if(run_vm==nullptr) {
            /* System-level OOM allocating this attempt's own VM -- give up
             * for good rather than spinning trying the same allocation
             * again; still needs to flip alive?() to false and explain
             * why, exactly like any other terminal outcome below. */
            pthread_mutex_lock(&supervisor->lock);
            snprintf(child->last_error,sizeof child->last_error,
                "out of memory allocating supervised run state");
            child->done=true;
            pthread_mutex_unlock(&supervisor->lock);
            break;
        }
        diamond_vm_init(run_vm);
        run_vm->range_class_index=child->program_template->range_class_index;
        run_vm->root_chunk=&child_chunk;
        if(supervisor->strategy!=DIAMOND_SUPERVISOR_ONE_FOR_ONE) {
            atomic_store(&child->interrupt,false);
            run_vm->interrupt_flag=&child->interrupt;
            run_vm->resource_limits_active=true;
        }
        /* Same defensive gc_protect-as-produced pattern DIAMOND_OP_THREAD_
         * NEW's own argument copy loop uses, for the identical reason: a
         * later argument's copy_value_into_vm call can itself trigger a
         * collection on run_vm before anything roots an earlier argument
         * already copied into it this iteration. */
        DiamondValue run_args[DIAMOND_MAX_ARGUMENTS]={};
        bool copy_failed=false;
        const size_t args_mark=run_vm->gc_protected_count;
        for(uint8_t index=0;index<child->arg_count;index++) {
            if(!copy_value_into_vm(run_vm,child->args[index],nullptr,
                    child->program_template->classes,
                    child->program_template->classes,nullptr,
                    &run_args[index])||
               !gc_protect(run_vm,run_args[index])) {
                copy_failed=true;break;
            }
        }
        gc_unprotect(run_vm,args_mark);
        DiamondValue run_result=DIAMOND_NIL;
        const DiamondVmStatus status=copy_failed?DIAMOND_VM_OUT_OF_MEMORY:
            run_chunk(&child_chunk,run_vm,run_args,child->arg_count,0,
                      nullptr,&run_result);
        pthread_mutex_lock(&supervisor->lock);
        if(status==DIAMOND_VM_OK) {
            child->done=true;
            pthread_mutex_unlock(&supervisor->lock);
            diamond_vm_free(run_vm);free(run_vm);
            break;
        }
        child->restart_count++;
        const bool interrupted_by_sibling=status==DIAMOND_VM_INTERRUPTED;
        if(interrupted_by_sibling) {
            /* Not this child's own crash: a sibling's failure restarted
             * it, and last_error says so. No restart delay below, since
             * this attempt wasn't failing on its own. */
            snprintf(child->last_error,sizeof child->last_error,
                "restarted: a sibling crashed");
        } else if(status==DIAMOND_VM_EXCEPTION) {
            format_uncaught_exception_message(run_vm,run_vm->exception,false);
            snprintf(child->last_error,sizeof child->last_error,"%s",run_vm->error);
        } else {
            const char *message=run_vm->error[0]!='\0'?run_vm->error:
                diamond_vm_status_name(status);
            snprintf(child->last_error,sizeof child->last_error,"%s",message);
        }
        if(!interrupted_by_sibling&&
           supervisor->strategy!=DIAMOND_SUPERVISOR_ONE_FOR_ONE&&
           !atomic_load(&supervisor->stop_requested)) {
            /* This child's own crash: take down the siblings its strategy
             * covers. Already-finished children (clean return) stay
             * finished, the same as for a plain crash. */
            const size_t first=supervisor->strategy==DIAMOND_SUPERVISOR_ONE_FOR_ALL?0:
                child->index+1;
            for(size_t other=first;other<supervisor->child_count;other++) {
                if(other==child->index||supervisor->children[other].done)continue;
                atomic_store(&supervisor->children[other].interrupt,true);
            }
        }
        pthread_mutex_unlock(&supervisor->lock);
        diamond_vm_free(run_vm);free(run_vm);
        if(atomic_load(&supervisor->stop_requested)) {
            /* stop() (or free_supervisor_reference) already blocks
             * joining this very thread once it returns, but alive?()
             * must also flip to false right away -- otherwise a caller
             * that checks alive?() right after stop() returns would
             * still see a stale "true" for a child that stopped here
             * rather than via a clean return. */
            pthread_mutex_lock(&supervisor->lock);
            child->done=true;
            pthread_mutex_unlock(&supervisor->lock);
            break;
        }
        if(interrupted_by_sibling)continue;
        struct timespec delay={.tv_nsec=20*1000*1000};
        nanosleep(&delay,nullptr);
    }
    atomic_fetch_sub(&diamond_active_thread_count,1);
    atomic_fetch_sub(&diamond_running_thread_count,1);
    return nullptr;
}

static DiamondSupervisorHandle *allocate_supervisor_handle(DiamondVm *vm,
        DiamondSupervisor *supervisor) {
    if (!maybe_collect(vm)) return nullptr;
    DiamondSupervisorHandle *handle=malloc(sizeof(DiamondSupervisorHandle));
    if(handle==nullptr)return nullptr;
    *handle=(DiamondSupervisorHandle){
        .object={.next=vm->young_objects,.kind=DIAMOND_OBJECT_SUPERVISOR},
        .supervisor=supervisor};
    vm->young_objects=&handle->object;
    vm->bytes_allocated+=sizeof(DiamondSupervisorHandle);
    return handle;
}

/* Shared by Supervisor#stop, Supervisor#join, and free_supervisor_
 * reference -- all three "join every child" call sites, any combination
 * of which may run against the same Supervisor over its lifetime.
 * pthread_join on an already-joined thread is undefined behavior (POSIX),
 * so each child's own `joined` flag (checked and set under `lock`) makes
 * the real pthread_join call idempotent regardless of how many times or
 * which of the three callers reach a given child first. Deliberately
 * does not touch stop_requested/stopped -- callers that need to actually
 * stop future restarts (Supervisor#stop, free_supervisor_reference) set
 * those themselves before calling this; Supervisor#join does not, so it
 * blocks only on children that finish on their own. */
static void supervisor_join_all_children(DiamondSupervisor *supervisor) {
    for(size_t index=0;index<supervisor->child_count;index++) {
        DiamondSupervisorChild *child=&supervisor->children[index];
        pthread_mutex_lock(&supervisor->lock);
        const bool already_joined=child->joined;
        child->joined=true;
        pthread_mutex_unlock(&supervisor->lock);
        if(!already_joined)pthread_join(child->handle,nullptr);
    }
}

/* Shared teardown for a DiamondSupervisor -- mirrors free_channel_
 * reference's own role/refcount discipline (only the last referencing
 * handle's sweep actually tears anything down), but additionally has to
 * *stop* every child first: sets stop_requested (same flag Supervisor#
 * stop sets) and blocks joining every child's OS thread (supervisor_
 * join_all_children above, exactly what stop() itself does) before
 * reclaiming any child's program_template/args_vm. A child mid-crash-
 * loop still finishes its *current* attempt before noticing the flag --
 * there is no cancellation anywhere in Diamond's concurrency model, same
 * as free_thread's own block-join reasoning for an abandoned Thread. */
static void free_supervisor_reference(DiamondSupervisor *supervisor) {
    if(supervisor==nullptr)return;
    if(atomic_fetch_sub(&supervisor->refcount,1)!=1)return;
    atomic_store(&supervisor->stop_requested,true);
    supervisor_join_all_children(supervisor);
    for(size_t index=0;index<supervisor->child_count;index++) {
        DiamondSupervisorChild *child=&supervisor->children[index];
        if(child->args_vm!=nullptr) {
            diamond_vm_free(child->args_vm);
            free(child->args_vm);
        }
        diamond_program_free(child->program_template);
        free(child->program_template);
    }
    pthread_mutex_destroy(&supervisor->lock);
    free(supervisor);
}

static DiamondFileHandle *allocate_file_handle(DiamondVm *vm,FILE *stream) {
    if (!maybe_collect(vm)) return nullptr;
    DiamondFileHandle *handle=malloc(sizeof(DiamondFileHandle));if(handle==nullptr)return nullptr;
    *handle=(DiamondFileHandle){.object={.next=vm->young_objects,.kind=DIAMOND_OBJECT_FILE},.stream=stream};
    vm->young_objects=&handle->object;vm->bytes_allocated+=sizeof(DiamondFileHandle);return handle;
}

DiamondListenerHandle *allocate_listener_handle(DiamondVm *vm,int fd,
        bool nonblocking) {
    if (!maybe_collect(vm)) return nullptr;
    DiamondListenerHandle *handle=malloc(sizeof(DiamondListenerHandle));
    if(handle==nullptr)return nullptr;
    *handle=(DiamondListenerHandle){.object={.next=vm->young_objects,.kind=DIAMOND_OBJECT_LISTENER},
        .fd=fd,.nonblocking=nonblocking};
    vm->young_objects=&handle->object;vm->bytes_allocated+=sizeof(DiamondListenerHandle);return handle;
}

DiamondSocketHandle *allocate_socket_handle(DiamondVm *vm,int fd) {
    if (!maybe_collect(vm)) return nullptr;
    DiamondSocketHandle *handle=malloc(sizeof(DiamondSocketHandle));
    if(handle==nullptr)return nullptr;
    *handle=(DiamondSocketHandle){.object={.next=vm->young_objects,.kind=DIAMOND_OBJECT_SOCKET},.fd=fd};
    vm->young_objects=&handle->object;vm->bytes_allocated+=sizeof(DiamondSocketHandle);return handle;
}

DiamondUdpSocketHandle *allocate_udp_socket_handle(DiamondVm *vm,int fd) {
    if (!maybe_collect(vm)) return nullptr;
    DiamondUdpSocketHandle *handle=malloc(sizeof(DiamondUdpSocketHandle));
    if(handle==nullptr)return nullptr;
    *handle=(DiamondUdpSocketHandle){
        .object={.next=vm->young_objects,.kind=DIAMOND_OBJECT_UDP_SOCKET},.fd=fd};
    vm->young_objects=&handle->object;vm->bytes_allocated+=sizeof(DiamondUdpSocketHandle);return handle;
}

static DiamondTlsSocketHandle *allocate_tls_socket_handle(DiamondVm *vm,SSL *ssl,int fd) {
    if (!maybe_collect(vm)) return nullptr;
    DiamondTlsSocketHandle *handle=malloc(sizeof(DiamondTlsSocketHandle));
    if(handle==nullptr)return nullptr;
    *handle=(DiamondTlsSocketHandle){
        .object={.next=vm->young_objects,.kind=DIAMOND_OBJECT_TLS_SOCKET},.ssl=ssl,.fd=fd};
    vm->young_objects=&handle->object;vm->bytes_allocated+=sizeof(DiamondTlsSocketHandle);return handle;
}

/* Signal.trap(name, handler) support. Deliberately a small, fixed set of
 * names rather than every signal POSIX knows about -- these three cover
 * "someone asked this process to stop" (INT: Ctrl+C, TERM: kill,
 * HUP: terminal/controlling-process hangup), the case a Diamond program
 * actually wants to react to (graceful server shutdown -- close
 * listening sockets, finish in-flight requests -- being the motivating
 * use case). SIGKILL/SIGSTOP can't be caught at the OS level regardless;
 * everything else (SIGSEGV, SIGCHLD, real-time signals, ...) is out of
 * scope for this first slice.
 *
 * File-scope (not DiamondVm fields) because signal delivery is a process-
 * wide OS concept, not a per-VM-instance one -- sigaction installs one
 * handler for the whole process regardless of which DiamondVm happens to
 * be running when it fires. The C handler itself only does what POSIX
 * guarantees is async-signal-safe: update a lock-free atomic bitmask and
 * return. Everything else -- resolving which Diamond closure to call,
 * actually calling it -- happens later, synchronously, from ordinary
 * (non-signal-handler) code that checks these flags at safe points: once
 * per bytecode instruction in run_chunk's own dispatch loop (see below),
 * and after EINTR from the handful of genuinely-blocking native calls
 * where waiting for the *next* bytecode instruction to run this check
 * could mean waiting arbitrarily long (TCPServer#accept, IO.poll,
 * UDPSocket#receive -- see their own opcode handlers). */
static const int diamond_signal_numbers[DIAMOND_SIGNAL_COUNT]={SIGINT,SIGTERM,SIGHUP};
static const char *const diamond_signal_names[DIAMOND_SIGNAL_COUNT]={"INT","TERM","HUP"};
/* Signal handlers must never enter an atomic library lock. All supported
 * targets provide lock-free unsigned int atomics. A single mask also avoids
 * losing a delivery between clearing a summary flag and its per-signal flag. */
static_assert(ATOMIC_INT_LOCK_FREE==2,"signal delivery requires lock-free int atomics");
static atomic_uint diamond_pending_signals=0;

static void diamond_signal_handler(int signal_number) {
    for(size_t index=0;index<DIAMOND_SIGNAL_COUNT;index++) {
        if(diamond_signal_numbers[index]==signal_number) {
            atomic_fetch_or_explicit(&diamond_pending_signals,1u<<index,memory_order_relaxed);
            return;
        }
    }
}

/* Invokes every currently-pending trapped signal's Diamond handler, in
 * signal-index order, synchronously -- via the same nested-run_chunk
 * mechanism DIAMOND_OP_CALL_CLOSURE itself uses, since a trapped handler
 * is an ordinary 0-arity Callable, not anything signal-specific at the
 * bytecode level. Claims each signal's pending bit before invoking its handler, not after --
 * a second delivery of the same signal *during* handler execution should
 * queue another invocation next time this runs, not be silently dropped
 * because the flag was still "pending" from the call already in
 * progress. Returns as soon as one handler's own status is non-OK
 * (an uncaught exception or worse from inside the handler itself) so the
 * caller can propagate it exactly like any other mid-dispatch failure;
 * remaining still-pending signals are simply handled on the next check
 * rather than lost. *any_invoked is purely informational for callers
 * that want to know whether anything actually happened (none of the
 * current call sites need it, but see docs/io.md before assuming it's
 * safe to drop -- future EINTR-retry call sites may want to distinguish
 * "a handler ran, retry" from "spurious EINTR, still retry" more
 * carefully than accept/poll/receive currently need to). */
DiamondVmStatus dispatch_pending_signals(DiamondVm *vm,const DiamondChunk *chunk,
        size_t depth,bool *any_invoked) {
    *any_invoked=false;
    if(!atomic_load_explicit(&diamond_pending_signals,memory_order_relaxed))return DIAMOND_VM_OK;
    for(size_t index=0;index<DIAMOND_SIGNAL_COUNT;index++) {
        /* A VM without this handler must leave the delivery for its owner.
         * Multiple eligible VMs atomically claim a coalesced delivery once. */
        if(vm->trapped_signal_handlers[index].kind!=DIAMOND_VALUE_OBJECT||
           vm->trapped_signal_handlers[index].as.object->kind!=DIAMOND_OBJECT_CLOSURE)
            continue;
        const unsigned bit=1u<<index;
        if(!(atomic_fetch_and_explicit(&diamond_pending_signals,~bit,memory_order_relaxed)&bit))
            continue;
        *any_invoked=true;
        const DiamondClosure *handler=
            (const DiamondClosure *)vm->trapped_signal_handlers[index].as.object;
        /* See DIAMOND_OP_CALL_CLOSURE's own comment -- a compile_method
         * result is scoped to define_method, not general Callable use. */
        if(handler->foreign_chunk!=nullptr)continue;
        if(handler->function_index>=chunk->function_count)continue;
        const DiamondFunction *fn=chunk->functions[handler->function_index];
        DiamondChunk child={.name=fn->name,.code=fn->code,.lines=fn->lines,
          .columns=fn->columns,.code_count=fn->code_count,.constants=fn->constants,
          .constant_count=fn->constant_count,.strings=fn->strings,.string_count=fn->string_count,
          .type_sets=fn->type_sets,.type_set_count=fn->type_set_count,
          .functions=chunk->functions,.function_count=chunk->function_count,
          .classes=chunk->classes,.class_count=chunk->class_count,
          .interfaces=chunk->interfaces,.interface_count=chunk->interface_count,
          .parameter_type_sets=fn->parameter_type_sets,
          .type_variable_count=fn->type_variable_count,
          .parameter_offset=fn->owner_class==UINT8_MAX?0:1,
          .register_count=fn->register_count};
        DiamondValue ignored=DIAMOND_NIL;
        const DiamondVmStatus status=run_chunk(&child,vm,nullptr,0,depth+1,handler,&ignored);
        if(status!=DIAMOND_VM_OK)return status;
    }
    return DIAMOND_VM_OK;
}

/* Shared getaddrinfo/socket/connect dance behind TCPSocket.connect and
 * TLSSocket.connect -- both need a connected fd before doing anything
 * TLS-specific, so this is exactly the code TCP_CONNECT's own handler
 * used to have inline, unchanged, just callable from a second opcode
 * handler now too. No SA_RESTART-style signal-retry here, matching the
 * existing TCPSocket.connect scope cut documented in docs/io.md: a
 * signal arriving mid-connect makes the attempt fail rather than
 * transparently resuming, same as it always has. */
/* Connects one already-created, non-blocking `fd` to `candidate`, waiting
 * up to `timeout_ms` for the kernel to finish a connection already in
 * progress (EINPROGRESS is the expected, common case for a non-blocking
 * connect -- not a failure). Returns 0 on a successful connection, -1
 * with `errno` set otherwise (ETIMEDOUT for a real timeout, whatever
 * `connect`/`poll`/`getsockopt` themselves reported otherwise) --
 * matching plain blocking `connect`'s own return convention so callers
 * don't need a second success path. */
int connect_with_timeout(int fd,const struct addrinfo *candidate,
        int64_t timeout_ms) {
    if(connect(fd,candidate->ai_addr,candidate->ai_addrlen)==0)return 0;
    if(errno!=EINPROGRESS)return -1;
    struct pollfd poll_fd={.fd=fd,.events=POLLOUT};
    const int poll_timeout=timeout_ms<0?-1:
        (timeout_ms>INT_MAX?INT_MAX:(int)timeout_ms);
    const int poll_result=poll(&poll_fd,1,poll_timeout);
    if(poll_result==0) {errno=ETIMEDOUT;return -1;}
    if(poll_result<0)return -1;
    int socket_error=0;socklen_t error_length=sizeof socket_error;
    if(getsockopt(fd,SOL_SOCKET,SO_ERROR,&socket_error,&error_length)!=0)return -1;
    if(socket_error!=0) {errno=socket_error;return -1;}
    return 0;
}

/* Resolver workers own only native data, never a VM, Diamond value, or a
 * pointer into the caller's heap. Cancellation abandons a reference rather
 * than joining libc's potentially unbounded getaddrinfo. Eight outstanding
 * workers bound the resources retained by abandoned lookups. */

/* Applies SO_RCVTIMEO/SO_SNDTIMEO to an already-connected fd -- a
 * negative value leaves the corresponding OS default (block forever)
 * untouched, so a caller that only wants one of the two only pays for
 * that one setsockopt call. A read/write that later times out surfaces
 * exactly like any other failed read/write already does (EAGAIN/
 * EWOULDBLOCK via errno, or SSL_get_error's matching case for a TLS
 * socket) -- no new error path, just a new way for the existing one to
 * trigger. */
static DiamondVmStatus apply_socket_timeouts_helper(DiamondVm *vm,int fd,
        int64_t read_timeout_ms,int64_t write_timeout_ms) {
    if(read_timeout_ms>=0) {
        const struct timeval tv={.tv_sec=(time_t)(read_timeout_ms/1000),
            .tv_usec=(suseconds_t)((read_timeout_ms%1000)*1000)};
        if(setsockopt(fd,SOL_SOCKET,SO_RCVTIMEO,&tv,sizeof tv)!=0) {
            snprintf(vm->error,sizeof vm->error,
                "cannot set read_timeout_ms: %s",strerror(errno));
            return DIAMOND_VM_IO_ERROR;
        }
    }
    if(write_timeout_ms>=0) {
        const struct timeval tv={.tv_sec=(time_t)(write_timeout_ms/1000),
            .tv_usec=(suseconds_t)((write_timeout_ms%1000)*1000)};
        if(setsockopt(fd,SOL_SOCKET,SO_SNDTIMEO,&tv,sizeof tv)!=0) {
            snprintf(vm->error,sizeof vm->error,
                "cannot set write_timeout_ms: %s",strerror(errno));
            return DIAMOND_VM_IO_ERROR;
        }
    }
    return DIAMOND_VM_OK;
}

/* One (key, kind, out-pointer) row per recognized `TCPSocket.connect`/
 * `TLSSocket.connect` options entry -- `kind` picks which one of
 * int_out/string_out/array_out the parse loop below writes into, so it
 * can type-check generically instead of repeating the same branches by
 * hand for every field. `DIAMOND_SOCKET_OPTION_ARRAY` (currently just
 * `alpn`) only validates "is this an Array" generically here -- its
 * element-by-element String check happens in the one caller that
 * actually interprets it (DIAMOND_OP_TLS_CONNECT), since encoding it
 * into OpenSSL's ALPN wire format is TLS-specific, not something a
 * TCPSocket.connect caller (which never reaches an array field at all,
 * since `allow_tls_fields` gates it out) needs to share. */
typedef enum {
    DIAMOND_SOCKET_OPTION_INT,
    DIAMOND_SOCKET_OPTION_STRING,
    DIAMOND_SOCKET_OPTION_ARRAY,
} DiamondSocketOptionKind;

typedef struct {
    const char *key;
    DiamondSocketOptionKind kind;
    int64_t *int_out;
    const DiamondString **string_out;
    const DiamondArray **array_out;
} DiamondSocketOptionField;

typedef struct {
    int64_t connect_timeout_ms;
    int64_t read_timeout_ms;
    int64_t write_timeout_ms;
    const DiamondString *ca_file;
    const DiamondString *ca_path;
    const DiamondString *cert;
    const DiamondString *key;
    const DiamondString *session;
    const DiamondArray *alpn;
} DiamondSocketConnectOptions;

/* `options_value` is Nil (nothing set, every field keeps its default) or
 * a Hash of recognized String keys -- anything else, or an unrecognized
 * key, is a TypeError, matching this codebase's existing "an unrecognized
 * name is a TypeError, not silently ignored" stance (see Signal.trap).
 * `allow_tls_fields` is false for TCPSocket.connect (ca_file/ca_path/
 * cert/key/session/alpn make no sense on a connection with no TLS layer
 * at all) and true for TLSSocket.connect. */
static DiamondVmStatus parse_socket_connect_options_helper(DiamondVm *vm,
        DiamondValue options_value,bool allow_tls_fields,
        DiamondSocketConnectOptions *out) {
    *out=(DiamondSocketConnectOptions){.connect_timeout_ms=-1,
        .read_timeout_ms=-1,.write_timeout_ms=-1};
    if(options_value.kind==DIAMOND_VALUE_NIL)return DIAMOND_VM_OK;
    if(options_value.kind!=DIAMOND_VALUE_OBJECT||
       options_value.as.object->kind!=DIAMOND_OBJECT_HASH) {
        snprintf(vm->error,sizeof vm->error,
            "connect options must be a Hash or nil");
        return DIAMOND_VM_TYPE_ERROR;
    }
    const DiamondHash *options=(const DiamondHash *)options_value.as.object;
    const DiamondSocketOptionField fields[]={
        {"connect_timeout_ms",DIAMOND_SOCKET_OPTION_INT,&out->connect_timeout_ms,nullptr,nullptr},
        {"read_timeout_ms",DIAMOND_SOCKET_OPTION_INT,&out->read_timeout_ms,nullptr,nullptr},
        {"write_timeout_ms",DIAMOND_SOCKET_OPTION_INT,&out->write_timeout_ms,nullptr,nullptr},
        {"ca_file",DIAMOND_SOCKET_OPTION_STRING,nullptr,&out->ca_file,nullptr},
        {"ca_path",DIAMOND_SOCKET_OPTION_STRING,nullptr,&out->ca_path,nullptr},
        {"cert",DIAMOND_SOCKET_OPTION_STRING,nullptr,&out->cert,nullptr},
        {"key",DIAMOND_SOCKET_OPTION_STRING,nullptr,&out->key,nullptr},
        {"session",DIAMOND_SOCKET_OPTION_STRING,nullptr,&out->session,nullptr},
        {"alpn",DIAMOND_SOCKET_OPTION_ARRAY,nullptr,nullptr,&out->alpn},
    };
    const size_t field_count=allow_tls_fields?
        sizeof fields/sizeof fields[0]:3;
    for(size_t index=0;index<options->count;index++) {
        const DiamondValue entry_key=options->entries[index].key;
        if(entry_key.kind!=DIAMOND_VALUE_OBJECT||
           entry_key.as.object->kind!=DIAMOND_OBJECT_STRING) {
            snprintf(vm->error,sizeof vm->error,"connect options Hash keys must be Strings");
            return DIAMOND_VM_TYPE_ERROR;
        }
        const DiamondString *entry_key_string=(const DiamondString *)entry_key.as.object;
        const DiamondSocketOptionField *matched=nullptr;
        for(size_t field_index=0;field_index<field_count;field_index++) {
            const size_t key_length=strlen(fields[field_index].key);
            if(entry_key_string->length==key_length&&
               memcmp(entry_key_string->chars,fields[field_index].key,key_length)==0) {
                matched=&fields[field_index];break;
            }
        }
        if(matched==nullptr) {
            snprintf(vm->error,sizeof vm->error,
                "unrecognized connect option '%.*s'",
                (int)entry_key_string->length,entry_key_string->chars);
            return DIAMOND_VM_TYPE_ERROR;
        }
        const DiamondValue entry_value=options->entries[index].value;
        if(matched->kind==DIAMOND_SOCKET_OPTION_STRING) {
            if(entry_value.kind!=DIAMOND_VALUE_OBJECT||
               entry_value.as.object->kind!=DIAMOND_OBJECT_STRING) {
                snprintf(vm->error,sizeof vm->error,
                    "connect option '%s' must be a String",matched->key);
                return DIAMOND_VM_TYPE_ERROR;
            }
            *matched->string_out=(const DiamondString *)entry_value.as.object;
        } else if(matched->kind==DIAMOND_SOCKET_OPTION_ARRAY) {
            if(entry_value.kind!=DIAMOND_VALUE_OBJECT||
               entry_value.as.object->kind!=DIAMOND_OBJECT_ARRAY) {
                snprintf(vm->error,sizeof vm->error,
                    "connect option '%s' must be an Array",matched->key);
                return DIAMOND_VM_TYPE_ERROR;
            }
            *matched->array_out=(const DiamondArray *)entry_value.as.object;
        } else {
            if(entry_value.kind!=DIAMOND_VALUE_INT) {
                snprintf(vm->error,sizeof vm->error,
                    "connect option '%s' must be an Int",matched->key);
                return DIAMOND_VM_TYPE_ERROR;
            }
            *matched->int_out=entry_value.as.integer;
        }
    }
    return DIAMOND_VM_OK;
}

/* Shared behind TLSServer.listen(port, cert_path, key_path): the same
 * plain-TCP listen tcp_listen_helper already does (a TLS listener is a
 * regular listening socket underneath -- the TLS part only starts once a
 * connection is actually accepted), plus loading the server's
 * certificate chain and private key into one SSL_CTX that every future
 * .accept() on this listener reuses (see DiamondListenerHandle's own
 * tls_context field comment for the lifetime story). Loaded once here
 * rather than per-connection specifically so a listener with a broken
 * cert/key pair fails loudly at TLSServer.listen time, not silently on
 * whichever connection happens to be first. */
/* TLSServer.listen's own (much smaller) options Hash: `alpn` (an Array of
 * protocol names) and `client_ca` (a String path to a PEM bundle of the
 * certificate authorities client certificates must chain to; giving it makes
 * the server request and require a verified client certificate). A
 * dedicated parser rather than reusing parse_socket_connect_options_helper's
 * table-driven approach, which exists to share seven fields across two call
 * sites; two fields nobody else shares don't earn that machinery. */
static DiamondVmStatus parse_tls_listen_options_helper(DiamondVm *vm,
        DiamondValue options_value,const DiamondArray **out_alpn,
        const DiamondString **out_client_ca) {
    *out_alpn=nullptr;*out_client_ca=nullptr;
    if(options_value.kind==DIAMOND_VALUE_NIL)return DIAMOND_VM_OK;
    if(options_value.kind!=DIAMOND_VALUE_OBJECT||
       options_value.as.object->kind!=DIAMOND_OBJECT_HASH) {
        snprintf(vm->error,sizeof vm->error,"TLSServer.listen options must be a Hash or nil");
        return DIAMOND_VM_TYPE_ERROR;
    }
    const DiamondHash *options=(const DiamondHash *)options_value.as.object;
    for(size_t index=0;index<options->count;index++) {
        const DiamondValue entry_key=options->entries[index].key;
        if(entry_key.kind!=DIAMOND_VALUE_OBJECT||
           entry_key.as.object->kind!=DIAMOND_OBJECT_STRING) {
            snprintf(vm->error,sizeof vm->error,
                "TLSServer.listen options Hash keys must be Strings");
            return DIAMOND_VM_TYPE_ERROR;
        }
        const DiamondString *entry_key_string=(const DiamondString *)entry_key.as.object;
        const DiamondValue entry_value=options->entries[index].value;
        if(entry_key_string->length==4&&memcmp(entry_key_string->chars,"alpn",4)==0) {
            if(entry_value.kind!=DIAMOND_VALUE_OBJECT||
               entry_value.as.object->kind!=DIAMOND_OBJECT_ARRAY) {
                snprintf(vm->error,sizeof vm->error,"TLSServer.listen option 'alpn' must be an Array");
                return DIAMOND_VM_TYPE_ERROR;
            }
            *out_alpn=(const DiamondArray *)entry_value.as.object;
        } else if(entry_key_string->length==9&&
                  memcmp(entry_key_string->chars,"client_ca",9)==0) {
            if(entry_value.kind!=DIAMOND_VALUE_OBJECT||
               entry_value.as.object->kind!=DIAMOND_OBJECT_STRING) {
                snprintf(vm->error,sizeof vm->error,
                    "TLSServer.listen option 'client_ca' must be a String path");
                return DIAMOND_VM_TYPE_ERROR;
            }
            *out_client_ca=(const DiamondString *)entry_value.as.object;
        } else {
            snprintf(vm->error,sizeof vm->error,
                "unrecognized TLSServer.listen option '%.*s'",
                (int)entry_key_string->length,entry_key_string->chars);
            return DIAMOND_VM_TYPE_ERROR;
        }
    }
    return DIAMOND_VM_OK;
}

/* Readiness is meaningful for TLS only while its handshake is pending.
 * Completed TLS sockets retain their blocking application I/O contract. */
static DiamondVmStatus pollable_fd(DiamondVm *vm,DiamondValue value,int *out_fd) {
    if(value.kind!=DIAMOND_VALUE_OBJECT||
       (value.as.object->kind!=DIAMOND_OBJECT_LISTENER&&
        value.as.object->kind!=DIAMOND_OBJECT_SOCKET&&
        value.as.object->kind!=DIAMOND_OBJECT_UDP_SOCKET&&
        value.as.object->kind!=DIAMOND_OBJECT_TLS_SOCKET&&
        value.as.object->kind!=DIAMOND_OBJECT_PROCESS_STREAM)) {
        snprintf(vm->error,sizeof vm->error,"IO.poll arguments must be nonblocking "
            "TCPServer listeners, their accepted Sockets, UDPSockets, or a Process.spawn stream");
        return DIAMOND_VM_TYPE_ERROR;
    }
    int fd=-1;
    const char *closed_message="cannot poll a closed listener/socket";
    if(value.as.object->kind==DIAMOND_OBJECT_LISTENER)
        fd=((DiamondListenerHandle *)value.as.object)->fd;
    else if(value.as.object->kind==DIAMOND_OBJECT_SOCKET)
        fd=((DiamondSocketHandle *)value.as.object)->fd;
    else if(value.as.object->kind==DIAMOND_OBJECT_TLS_SOCKET) {
        DiamondTlsSocketHandle *tls=(DiamondTlsSocketHandle *)value.as.object;
        if(!tls->handshake_pending) {
            snprintf(vm->error,sizeof vm->error,"IO.poll only supports TLS sockets during their handshake");
            return DIAMOND_VM_TYPE_ERROR;
        }
        fd=tls->fd;
    } else if(value.as.object->kind==DIAMOND_OBJECT_UDP_SOCKET) {
        fd=((DiamondUdpSocketHandle *)value.as.object)->fd;
        closed_message="cannot poll a closed UDP socket";
    } else {
        fd=((DiamondProcessStream *)value.as.object)->fd;
        closed_message="cannot poll a closed process stream";
    }
    if(fd<0) {
        snprintf(vm->error,sizeof vm->error,"%s",closed_message);
        return DIAMOND_VM_IO_ERROR;
    }
    *out_fd=fd;
    return DIAMOND_VM_OK;
}

/* Diamond's readables/writables are separate Arrays (see DIAMOND_OP_IO_POLL
 * below for why -- avoids needing Array#include?/object-identity checks on
 * the Diamond side), but the same fd can legitimately appear in both --
 * poll(2) itself keys purely by fd, so registering it twice would just
 * overwrite events instead of OR-ing them together. Returns false only
 * when max_fds is exhausted by a genuinely new fd. */
static bool poll_register_fd(struct pollfd *fds,nfds_t *fd_count,size_t max_fds,
        int fd,short want_events,size_t *out_slot) {
    for(size_t existing=0;existing<*fd_count;existing++) {
        if(fds[existing].fd==fd) {
            fds[existing].events=(short)(fds[existing].events|want_events);
            *out_slot=existing;
            return true;
        }
    }
    if(*fd_count>=max_fds)return false;
    fds[*fd_count]=(struct pollfd){.fd=fd,.events=want_events,.revents=0};
    *out_slot=*fd_count;
    (*fd_count)++;
    return true;
}

static DiamondSqlite3Handle *allocate_sqlite3_handle(DiamondVm *vm,sqlite3 *db) {
    if (!maybe_collect(vm)) return nullptr;
    DiamondSqlite3Handle *handle=malloc(sizeof(DiamondSqlite3Handle));
    if(handle==nullptr)return nullptr;
    *handle=(DiamondSqlite3Handle){.object={.next=vm->young_objects,.kind=DIAMOND_OBJECT_SQLITE3},
        .db=db};
    vm->young_objects=&handle->object;vm->bytes_allocated+=sizeof(DiamondSqlite3Handle);return handle;
}

DiamondSqlite3StatementHandle *allocate_sqlite3_statement_handle(
        DiamondVm *vm,sqlite3_stmt *stmt) {
    if (!maybe_collect(vm)) return nullptr;
    DiamondSqlite3StatementHandle *handle=malloc(sizeof(DiamondSqlite3StatementHandle));
    if(handle==nullptr)return nullptr;
    *handle=(DiamondSqlite3StatementHandle){
        .object={.next=vm->young_objects,.kind=DIAMOND_OBJECT_SQLITE3_STATEMENT},.stmt=stmt};
    vm->young_objects=&handle->object;
    vm->bytes_allocated+=sizeof(DiamondSqlite3StatementHandle);
    return handle;
}

